comms.text:
@1 וּקְרֵב לְוָתֵהּ יְהוּדָה וַאֲמַר בְּבָעוּ רִבּוֹנִי יְמַלֵּל כְּעַן עַבְדָּךְ פִּתְגָּמָא קֳדָם רִבּוֹנִי וְלָא יִתְקֵף רוּגְזָךְ בְּעַבְדָּךְ אֲרֵי כְפַרְעֹה כֵּן אָתְּ:
@2 רִבּוֹנִי שְׁאִיל יָת עַבְדּוֹהִי לְמֵימָר הַאִית לְכוֹן אַבָּא אוֹ אָחָא:
@3 וַאֲמַרְנָא לְרִבּוֹנִי אִית לָנָא אַבָּא סָבָא וּבַר סִיבְתִין זְעֵיר וְאָחוּהִי מִית וְאִשְׁתָּאַר הוּא בִלְחוֹדוֹהִי לְאִמֵּהּ וַאֲבוּהִי רְחִים לֵהּ:
@4 וַאֲמַרְתָּ לְעַבְדָּיךְ אֲחִיתוֹהִי לְוָתִי וֶאֱשַׁוֵּי עֵינִי עֲלוֹהִי:
@5 וַאֲמַרְנָא לְרִבּוֹנִי לָא יִכּוּל עוּלֵימָא לְמִשְׁבַּק יָת אֲבוּהִי וְאִם יִשְׁבּוֹק יָת אֲבוּהִי וּמִית:
@6 וַאֲמַרְתָּ לְעַבְדָּיךְ אִם לָא יֵחוֹת אֲחוּכוֹן זְעֵירָא עִמְּכוֹן לָא תוֹסְפוּן לְמֶחֱזֵי אַפָּי:
@7 וַהֲוָה כַּד סְלֵיקְנָא לְעַבְדָּךְ אַבָּא וְחַוֵּינָא לֵהּ יָת פִּתְגָּמֵי רִבּוֹנִי:
@8 וַאֲמַר אָבוּנָא תּוּבוּ זְבוּנוּ לָנָא זְעֵיר עִיבוּרָא:
@9 וַאֲמַרְנָא לָא נִכּוּל לְמֵיחָת אִם אִית אָחוּנָא זְעֵירָא עִמָּנָא וְנֵחוֹת אֲרֵי לָא נִכּוּל לְמֶחֱזֵי אַפֵּי גַּבְרָא וְאָחוּנָא זְעֵירָא לֵיתוֹהִי עִמָּנָא:
@10 וַאֲמַר עַבְדָּךְ אַבָּא לָנָא אַתּוּן יְדַעְתּוּן אֲרֵי תְרֵין יְלִידַת לִי אִתְּתִי:
@11 וּנְפַק חַד מִלְוָתִי וַאֲמָרִית בְּרַם מִקְטַל קְטִיל וְלָא חֲזִתֵּהּ עַד כְּעָן:
@12 וְתַדְבְּרוּן אַף יָת דֵּין מִן קֳדָמַי וִיעַרְעִנֵּהּ מוֹתָא וְתַחֲתוּן יָת שִׂבְתִי בְּבִישְׁתָא לִשְׁאוֹל:
@13 וּכְעַן כְּמֵיתִי לְוַת עַבְדָּךְ אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמָּנָא וְנַפְשֵׁהּ חֲבִיבָא לֵהּ כְּנַפְשֵׁהּ:
@14 וִיהֵי כַּד יֶחֱזֵי אֲרֵי לֵית עוּלֵימָא וּמִית וְיַחֲתוּן עַבְדָּיךְ יָת שִׂיבַת עַבְדָּךְ אָבוּנָא בְּדָווֹנָא לִשְׁאוֹל:
@15 אֲרֵי עַבְדָּךְ מְעָרַב בְּעוּלֵימָא מִן אַבָּא לְמֵימָר אִם לָא אַיְתִנֵּהּ לְוָתָךְ וָאֱהִי חָטֵי לְאַבָּא כָּל יוֹמַיָּא:
@16 וּכְעַן יֵתֶב כְּעַן עַבְדָּךְ תְּחוֹת עוּלֵימָא עַבְדָּא לְרִבּוֹנִי וְעוּלֵימָא יִסַּק עִם אֲחוֹהִי:
@17 אֲרֵי אֶכְדֵּין אֶסַּק לְוַת אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמִּי דִּלְמָא אֶחֱזֵי בְּבִישׁוּ דִּי יִשְׁכַּח יָת אַבָּא:
@18 וְלָא יְכִיל יוֹסֵף לְאִתְחַסָּנָא לְכֹל דְּקָיְמִין עִלָּוֹהִי וּקְרָא אַפִּיקוּ כָל אֱנַשׁ מֵעִלָּוָי וְלָא קָם אֱנַשׁ עִמֵּהּ כַּד אִתְיְדַע יוֹסֵף לְוַת אֲחוֹהִי:
@19 וִיהַב יָת קָלֵהּ בִּבְכִיתָא וּשְׁמָעוּ מִצְרַיִם וּשְׁמַע אֱנַשׁ בֵּית פַּרְעֹה:
@20 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא יוֹסֵף הַעַד כְּעַן אַבָּא קַיָּם וְלָא יָכִילוּ אֲחוֹהִי לַאֲתָבָא יָתֵהּ פִּתְגָּם ארֵי אִתְבְּהִילוּ מִן קֳדָמוֹהִי:
@21 וַאֲמַר יוֹסֵף לַאֲחוֹהִי קְרִיבוּ כְעַן לְוָתִי וּקְרִיבוּ וַאֲמַר אֲנָא יוֹסֵף אֲחוּכוֹן דִּי זַבִּנְתּוּן יָתִי לְמִצְרָיִם:
@22 וּכְעַן לָא תִתְנַסְסוּן וְלָא יִתְקָף בְּעֵינֵיכוֹן אֲרֵי זַבִּנְתּוּן יָתִי הַלְכָא אֲרֵי לְקַיָּמָא שַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן:
@23 אֲרֵי דְנַן תַּרְתֵּין שְׁנִין כַּפְנָא בְּגוֹ אַרְעָא וְעוֹד חָמֵשׁ שְׁנִין דִּי לֵית זְרוֹעָא וַחֲצָדָא:
@24 וְשַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן לְשַׁוָּאָה לְכוֹן שְׁאָרָא בְּאַרְעָא וּלְקַיָּמָא לְכוֹן לְשֵׁיזָבָא רַבָּא:
@25 וּכְעַן לָא אַתּוּן שְׁלַחְתּוּן יָתִי הַלְכָא אֶלָּהֵן מִן קֳדָם יְיָ וְשַׁוְּיַנִי לְאַבָּא לְפַרְעֹה וּלְרִבּוֹן לְכָל אֱנַשׁ בֵּיתֵהּ וְשַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם:
@26 אוֹחוּ וּסְקוֹ לְוַת אַבָּא וְתֵימְרוּן לֵהּ כִּדְנַן אֲמַר בְּרָךְ יוֹסֵף שַׁוְּיַנִי יְיָ לְרִבּוֹן לְכָל מִצְרָיִם חוּת לְוָתִי לָא תִתְעַכָּב:
@27 וְתֵתֵב בְּאַרְעָא דְגשֶׁן וּתְהֵי קָרִיב לִי אַתְּ וּבְנָיךְ וּבְנֵי בְנָיךְ וְעָנָךְ וְתוֹרָךְ וְכָל דִּי לָךְ:
@28 וְאֵזוּן יָתָךְ תַּמָּן אֲרֵי עוֹד חֲמֵשׁ שְׁנִין כַּפְנָא דִּלְמָא תִתְמַסְכַּן אַתְּ וֶאֱנַשׁ בֵּיתָךְ וְכָל דִּי לָךְ:
@29 וְהָא עֵינֵיכוֹן חֲזָן וְעֵינֵי אָחִי בִנְיָמִין אֲרֵי בְלִישַׁנְכוֹן אֲנָא מְמַלֵּל עִמְּכוֹן:
@30 וּתְחַווּן לְאַבָּא יָת כָּל יְקָרִי בְּמִצְרַיִם וְיָת כָּל דִּי חֲזֵיתוּן וְתוֹחוּן וְתַחֲתוּן יָת אַבָּא הָכָא:
@31 וּנְפַל עַל צַוְּארֵי בִנְיָמִן אֲחוּהִי וּבְכָא וּבִנְיָמִן בְּכָא עַל צַוְּארֵהּ:
@32 וּנְשַׁק לְכָל אֲחוֹהִי וּבְכָא עֲלֵיהוֹן וּבָתַר כֵּן מַלִּילוּ אֲחוֹהִי עִמֵּהּ:
@33 וְקָלָא אִשְׁתְּמַע בֵית פַּרְעֹה לְמֵימַר עַלּוּ אֲחֵי יוֹסֵף וּשְׁפַר בְּעֵינֵי פַרְעֹה וּבְעֵינֵי עַבְדּוֹהִי:
@34 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֱמַר לְאַחָיךְ דָּא עִיבִידוּ טְעוּנוּ יָת בְּעִירְכוֹן וֶאֱזִילוּ אוֹבִילוּ לְאַרְעָא דִּכְנָעַן:
@35 וּדְבָרוּ יָת אֲבוּכוֹן וְיָת אֱנַשׁ בָּתֵּיכוֹן וְעוּלוּ לְוָתִי וְאֶתֵּן לְכוֹן יָת טוּב אַרְעָא דְמִצְרַיִם וְתֵיכְלוּן יָת טוּבָא דְאַרְעָא:
@36 וְאַתְּ מְפַקָּדָא דָּא עִיבִידוּ סִיבוּ לְכוֹן מֵאַרְעָא דְמִצְרַיִם עֶגְלָן לְטַפְלֵּיכוֹן וְלִנְשֵׁיכוֹן וְתִטְּלוּן יָת אֲבוּכוֹן וְתֵיתוּן:
@37 וְעֵינְכוֹן לָא תְחוּס עַל מָנֵיכוֹן אֲרֵי טַב כָּל אַרְעָא דְמִצְרַיִם דִּלְכוֹן הוּא:
@38 וַעֲבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וִיהַב לְהוֹן יוֹסֵף עֶגְלָן עַל מֵימַר פַּרְעֹה וִיהַב לְהוֹן זְוָדִין לְאָרְחָא:
@39 לְכָלְהוֹן יְהַב לִגְבַר אִצְטְלַּוָּן דִּלְבוּשִׁין וּלְבִנְיָמִן יְהַב תְּלַת מְאָה סִלְעִין דִּכְסַף וַחֲמֵשׁ אִצְטְלַוָּן דִּלְבוּשִׁין:
@40 וְלַאֲבוּהִי שְׁלַח כְּדָא עַסְרָא חֲמָרִין טְעִינִין מִטּוּבָא דְמִצְרָיִם וַעֲסַר אַתְנָן טְעִינָן עִיבוּר וּלְחֵם וּזְוָדִין לַאֲבוּהִי לְאָרְחָא:
@41 וְשַׁלַּח יָת אֲחוֹהִי וַאֲזָלוּ וַאֲמַר לְהוֹן לָא תִתְנַצוּן:בּאָ:רחָא:
@42 וּסְלִיקוּ מִמִּצְרָיִם וַאֲתוֹ לְאַרְעָא דִּכְנַעַן לְוַת יַעֲקֹב אֲבוּהוֹן:
@43 וְחַוִּיאוּ לֵהּ לְמֵימַר עַד כְּעַן יוֹסֵף קַיָּם וַאֲרֵי הוּא שַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם וַהֲווֹ מִלַּיָּא פָּיְגָן עַל לִבֵּהּ אֲרֵי לָא הֵימִין לְהוֹן:
@44 וּמַלִּילוּ עִמֵּהּ יָת כָּל פִּתְגָּמֵי יוֹסֵף דִּי מַלִּיל עִמְּהוֹן וַחֲזָא יָת עֲגַלָּתָא דִּשְׁלַח יוֹסֵף לְמִטַּל יָתֵהּ וּשְׁרַת רוּחַ נְבוּאָה עַל יַעֲקֹב אֲבוּהוֹן:
@45 וַאֲמַר יִשְׂרָאֵל סַגִּי לִי חֶדְוָא עַד כְּעַן יוֹסֵף בְּרִי קַיָּם אֱזֵיל וְאֶחֱזִנֵּהּ עַד לָא אֵמוּת:
@46 וּנְטַל יִשְׂרָאֵל וְכָל דִּי לֵהּ וַאֲתָא לִבְאֵר שָׁבַע וּדְבַח דִּבְחִין לֵאלָהָא דְאֲבוּהִי יִצְחָק:
@47 וַאֲמַר יְיָ לְיִשְׂרָאֵל בְּחֶזְוֵי דְלֵילְיָא וַאֲמַר יַעֲקֹב יַעֲקֹב וַאֲמַר הָא אֲנָא:
@48 וַאֲמַר אֲנָא אֵל אֱלָהָא דְאָבוּךְ לָא תִדְחַל מִלְּמֵיחַת לְמִצְרַיִם אֲרֵי לְעַם סַגִּי אֲשֵׁוִּנָּךְ תַּמָּן:
@49 אֲנָא אֵחוֹת עִמָּךְ לְמִצְרַיִם וַאֲנָא אַסֵּקִנָּךְ אַף אַסָּקָא וְיוֹסֵף יְשַׁוֵּי יְדוֹהִי עַל עֵינָיךְ:
@50 וְקָם יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וּנְטָלוּ בְנֵי יִשְׂרָאֵל יָת יַעֲקֹב אֲבוּהוֹן וְיָת טַפְלְהוֹן וְיָת נְשֵׁיהוֹן בַּעֲגַלְתָּא דִּי שְׁלַח פַּרְעֹה לְמִטַּל יָתֵהּ:
@51 וּדְבָרוּ יָת גֵּיתֵיהוֹן וְיָת קִנְיָנְהוֹן דִּי קְנוֹ בְּאַרְעָא דִּכְנַעַן וַאֲתוֹ לְמִצְרָיִם יַעֲקֹב וְכָל בְּנוֹהִי עִמֵּהּ:
@52 בְּנוֹהִי וּבְנֵי בְנוֹהִי עִמֵּהּ בְּנָתֵהּ וּבְנַת בְּנוֹהִי וְכָל זַרְעֵהּ אַיְתִי עִמֵּהּ לְמִצְרָיִם:
@53 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׂרָאֵל דְּעַלּוּ לְמִצְרַיִם יַעֲקֹב וּבְנוֹהִי בּוּכְרָא דְיַעֲקֹב רְאוּבֵן:
@54 וּבְנֵי רְאוּבֵן חֲנוֹךְ וּפַלּוּא וְחֶצְרֹן וְכַרְמִי:
@55 וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בַּר כְּנַעֲנֵיתָא:
@56 וּבְנֵי לֵוִי גֵּרְשׁוֹן קְהָת וּמְרָרִי:
@57 וּבְנֵי יְהוּדָה עֵר וְאוֹנָן וְשֵׁלָה וָפֶרֶץ וָזָרַח וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִּכְנַעַן וַהֲווֹ בְנֵי פֶרֶץ חֶצְרֹן וְחָמוּל:
@58 וּבְנֵי יִשָּׂשכָר תּוֹלָע וּפֻוָּה וְיוֹב וְשִׁמְרוֹן:
@59 וּבְנֵי זְבֻלוּן סֶרֶד וְאֵלוֹן וְיַחְלְאֵל:
@60 אִלֵּין בְּנֵי לֵאָה דִּילִידַת לְיַעֲקֹב בְּפַדַּן אֲרָם וְיָת דִּינָה בְרַתֵּהּ כָּל נֶפֶשׁ בְּנוֹהִי וּבְנָתֵהּ תְּלָתִין וּתְלָת:
@61 וּבְנֵי גָד צִפְיוֹן וְחַגִּי שׁוּנִי וְאֶצְבּוֹן עֵרִי וַאֲרוֹדִי וְאַרְאֵלִי:
@62 וּבְנֵי אָשֵׁר יִמְנָה וְיִשְׁוָה וְיִשְׁוִי וּבְרִיעָה וְשֶׂרַח אֲחַתְהוֹן וּבְנֵי בְרִיעָה חֶבֶר וּמַלְכִּיאֵל:
@63 אִלֵּין בְּנֵי זִלְפָּה דִי יְהַב לָבָן לְלֵאָה בְרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב שִׁית עֶשְׂרֵי נַפְשָׁא:
@64 בְּנֵי רָחֵל אִתַּת יַעֲקֹב יוֹסֵף וּבִנְיָמִן:
@65 וְאִתְיְלִידוּ לְיוֹסֵף בְּאַרְעָא דְמִצְרַיִם דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@66 וּבְנֵי בִנְיָמִן בֶּלַע וָבֶכֶר וְאַשְׁבֵּל גֵּרָא וְנַעֲמָן אֵחִי וָרֹאשׁ מֻפִּים וְחֻפִּים וָאָרְדְּ:
@67 אִלֵּין בְּנֵי רָחֵל דְּאִתְיְלִידוּ לְיַעֲקֹב כָּל נַפְשָׁא אַרְבָּעָה עֲשָׂר:
@68 וּבְנֵי דָן חֻשִׁים:
@69 וּבְנֵי נַפְתָּלִי יַחְצְאֵל וְגוּנִי וְיֵצֶר וְשִׁלֵּם:
@70 אִלֵּין בְּנֵי בִלְהָה דִּיהַב לָבָן לְרָחֵל בְּרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב כָּל נַפְשָׁא שִׁבְעָא:
@71 כָּל נַפְשָׁא דְּעַלָּא לְיַעֲקֹב לְמִצְרַיִם נָפְקֵי יַרְכֵּהּ בַּר מִנְּשֵׁי בְנֵי יַעֲקֹב כָּל נַפְשָׁתָא שִׁתִּין וְשִׁית:
@72 וּבְנֵי יוֹסֵף דִּי אִתְיְלִידוּ לֵהּ בְּמִצְרַיִם נַפְשָׁתָא תְרֵין כָּל נַפְשָׁתָא לְבֵית יַעֲקֹב דְּעַלּוּ לְמִצְרַיִם שִׁבְעִין:
@73 וְיָת יְהוּדָה שְׁלַח קֳדָמוֹהִי לְוַת יוֹסֵף לְפַנָּאָה קֳדָמוֹהִי לְגשֶׁן וַאֲתוֹ לְאַרְעָא דְגשֶׁן:
@74 וְטַקֵּיס יוֹסֵף רְתִכּוֹהִי וּסְלֵיק לְקַדָּמוּת יִשְׂרָאֵל אֲבוּהִי לְגשֶׁן וְאִתְגְּלִי לֵהּ וּנְפַל עַל צַוְארֵהּ וּבְכָא עַל צַוְארֵהּ עוֹד:
@75 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף אִלּוּ אֲנָא מָאִית זִמְנָא הָדָא מְנַחֵם אֲנָא בָּתַר דַּחֲזֵיתִי יָת אַפָיךְ אֲרֵי עַד כְּעַן אַתְּ קַיָּם:
@76 וַאֲמַר יוֹסֵף לַאֲחוֹהִי וּלְבֵית אֲבוּהִי אֶסַּק וְאֵחַוֵּי לְפַרְעֹה וְאֵימַר לֵהּ אַחַי וּבֵית אַבָּא דִּי בְאַרְעָא דִּכְנַעַן עַלּוּ לְוָתִי:
@77 וְגֻּבְרַיָּא רָעֵי עָנָא אֲרֵי גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אַיְתִיאוּ:
@78 וִיהֵי אֲרֵי יִקְרֵי לְכוֹן פַּרְעֹה וְיֵימַר מָה עוֹבָדֵיכוֹן:
@79 וְתֵימְרוּן גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ עַבְדָּיךְ מֵעוּלֵמָנָא וְעַד כְּעַן אַף אֲנַחְנָא אַף אַבְהָתָנָא בְּדִיל דִּי תֵיתְבוּן בְּאַרְעָא דְגשֶׁן אֲרֵי מְרַחֲקִין מִצְרָאֵי כָּל רָעֵי עָנָא:
@80 וַאֲתָא יוֹסֵף וְחַוִּי לְפַרְעֹה וַאֲמַר אַבָּא וְאַחַי וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אֲתוֹ מֵאַרְעָא דִּכְנָעַן וְהָא אִנּוּן בְּאַרְעָא דְגשֶׁן:
@81 וּמִקְצַת מִן אֲחוֹהִי דְּבַר חַמְשָׁא גֻּבְרִין וַאֲקֵימִנּוּן קֳדָם פַּרְעֹה:
@82 וַאֲמַר פַּרְעֹה לַאֲחוֹהִי מָה עוֹבָדֵיכוֹן וַאֲמָרוּ לְפַרְעֹה רָעֵי עָנָא עַבְדָּיךְ אַף אֲנַחְנָא אַף אֲבָהָתָנָא:
@83 וַאֲמָרוּ לְוַת פַּרְעֹה לְאִתּוֹתָבָא בְאַרְעָא אֲתֵינָא אֲרֵי לֵית רַעֲיָא לְעָנָא דִּי לְעַבְדָּיךְ אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא דִּכְנָעַן וּכְעַן יֵתְבוּן כְּעַן עַבְדָּיךְ בְּאַרְעָא דְגשֶׁן:
@84 וַאֲמַר פַּרְעֹה לְיוֹסֵף לְמֵימָר אֲבוּךְ וְאַחָיךְ אֲתוֹ לְוָתָךְ:
@85 אַרְעָא דְמִצְרַיִם קֳדָמָךְ הִיא בִּדְשַׁפִּיר בְּאַרְעָא אוֹתֵיב יָת אֲבוּךְ וְיָת אַחָיךְ יֵתְבוּן בְּאַרְעָא דְגשֶׁן וְאִם יָדַעְתְּ וְאִית בְּהוֹן גֻּבְרִין דְּחֵילָא וּתְמַנִּנוּן רַבָּנֵי גֵיתֵי עַל דִּי לִי:
@86 וְאַיְתִי יוֹסֵף יָת יַעֲקֹב אֲבוּהִי וַאֲקִימִנֵּהּ קֳדָם פַּרְעֹה וּבְרִיךְ יַעֲקֹב יָת פַּרְעֹה:
@87 וַאֲמַר פַּרְעֹה לְּיַעֲקֹב כַּמָּה יוֹמֵי שְׁנֵי חַיָּיךְ:
@88 וַאֲמַר יַעֲקֹב לְפַרְעֹה יוֹמֵי שְׁנֵי תוֹתָבוּתַי מְאָה וּתְלָתִין שְׁנִין זְעֵירִין וּבִישִׁין הֲווֹ יוֹמֵי שְׁנֵי חַיַּי וְלָא אַדְבִּיקוּ יָת יוֹמֵי שְׁנֵי חַיֵּי אֲבָהָתַי בְּיוֹמֵי תּוֹתָבוּתְהוֹן:
@89 וּבָרִיךְ יַעֲקֹב יָת פַּרְעֹה וּנְפַק מִן קֳדָם פַּרְעֹה:
@90 וְאוֹתֵיב יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וִיהַב לְהוֹן אַחֲסָנָא בְּאַרְעָא דְמִצְרַיִם בִּדְשַׁפִּיר בְּאַרְעָא בְּאַרְעָא דְרַעְמְסֵס כְּמָא דִי פַקֵּיד פַרְעֹה:
@91 וְזָן יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וְיָת כָּל בֵּית אֲבוּהִי לַחְמָא לְפוּם טַפְלָא:
@92 וְלַחֲמָא לֵית בְּכָל אַרְעָא אֲרֵי תַקִּיף כַּפְנָא לַחֲדָא וְאִשְׁתַּלְהֵי עַמָּא דְאַרְעָא דְמִצְרַיִם וְעַמָּא דְאַרְעָא דִּכְנַעַן מִן קֳדָם כַּפְנָא:
@93 וְלַקִּיט יוֹסֵף יָת כָּל כַּסְפָּא דְּאִשְׁתְּכַח בְּאַרְעָא דְמִצְרַיִם וּבְאַרְעָא דִּכְנַעַן בְּעִיבוּרָא דִּי אִנּוּן זָבְנִין וְאַיְתִי יוֹסֵף יָת כַּסְפָּא לְבֵית פַּרְעֹה:
@94 וּשְׁלִים כַּסְפָא מֵאַרְעָא דְמִצְרַיִם וּמֵאַרְעָא דִּכְנַעַן וַאֲתוֹ כָּל מִצְרָאֵי לְוַת יוֹםֵף לְמֵימַר הַב לָנָא לַחֲמָא וּלְמָה נְמוּת לְקִבְלָךְ אֲרֵי שְׁלִים כַּסְפָּא:
@95 וַאֲמַר יוֹסֵף הָבוּ גֵּיתֵיכוֹן וְאֶתֵּן לְכוֹן בְּגֵּיתֵיכוֹן אִם שְׁלִים כַּסְפָּא:
@96 וְאַיְתִיּוּ יָת גֵּיתֵיהוֹן לְוַת יוֹסֵף וִיהַב לְהוֹן יוֹסֵף לַחְמָא בְּסוּסְוָתָא וּבְגֵיתֵי עָנָא וּבְגֵיתֵי תוֹרִין וּבַחֲמָרִין וְזָנִנּוּן בְּלַחֲמָא בְּכָל גֵּיתֵיהוֹן בְּשַׁתָּא הַהִיא:
@97 וּשְׁלִימַת שַׁתָּא הַהִיא וַאֲתוֹ לְוָתֵהּ בְּשַׁתָּא תִנְיֵתָא וַאֲמָרוּ לֵהּ לָא נְכַסֵּי מִן רִבּוֹנִי אֶלָּהֵין שְׁלִים כַּסְפָּא וְגֵּיתֵי בְעִירָא לְוַת רִבּוֹנִי לָא אִשְׁתָּאַר קֳדָם רִבּוֹנִי אֶלָּהֵין גְּוִיָתָנָא וְאַרְעָנָא:
@98 לְמָה נְמוּת לְעֵינָיךְ אַף אֲנַחְנָא אַף אַרְעָתָנָא קְנֵי יָתָנָא וְיָת אַרְעָתָנָא בְּלַחְמָא וּנְהֵי אֲנַחְנָא וְאַרְעָתָנָא עַבְדִּין לְפַרְעֹה וְהַב בַּר זַרְעָא וְנֵיחֵי וְלָא נְמוּת וְאַרְעָא לָא תְבוּר:
@99 וּקְנָא יוֹסֵף יָת כָּל אַרְעָא דְמִצְרַיִם לְפַרְעֹה אֲרֵי זַבִּינוּ מִצְרַיִם גְּבַר חַקְלֵהּ אֲרֵי תְקֵיף עֲלֵיהוֹן כַּפְנָא וַהֲוַת אַרְעָא לְפַרְעֹה:
@100 וְיָת עַמָּא אַעְבֵּר יָתֵהּ מִקְּרֵי לִקְרֵי מִסְּיָפֵי תְּחוּם מִצְרַיִם וְעַד סוֹפֵהּ:
@101 לְחוֹד אַרְעָא דְכֻמָּרַיָּא לָא זַבִּין אֲרֵי חֳלָקָא לְכֻמָּרַיָּא מִלְּוַת פַּרְעֹה וְאָכְלִין יָת חֳלָקְהוֹן דִּי יְהַב לְהוֹן פַּרְעֹה עַל כֵּן לָא זַבִּינוּ יָת אַרְעֲהוֹן:
@102 וַאֲמַר יוֹסֵף לְעַמָּא הָא זְבֵנִית יָתְכוֹן יוֹמָא דֵּין וְיָת אַרְעֲכוֹן לְפַרְעֹה הֵא לְכוֹן בַּר זַרְעָא וְתִזְרְעוּן יָת אַרְעָא:
@103 וִיהֵי בְּאָעוֹלֵי עֲלַלְתָּא וְתִתְּנוּן חַד מִן חַמְשָׁא לְפַרְעֹה וְאַרְבַּע חֳלָקִין יְהֵא לְכוֹן לְבַר זְרַע חַקְלָא וּלְמֵיכַלְכוֹן וְלֶאֱנַשׁ בָתֵּיכוֹן וּלְמֵיכַל לְטַפְלְכוֹן:
@104 וַאֲמָרוּ קַיִּמְתָּנָא נִשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי וּנְהֵי עַבְדִּין לְפַרְעֹה:
@105 וְשַׁוִּי יָתַהּ יוֹסֵף לִגְזֵרָא עַד יוֹמָא הָדֵין עַל אַרְעָא דְמִצְרַיִם דִּיהוֹן יָהֲבִין חַד מִן חַמְשָׁא לְפַרְעֹה לְחוֹד אַרְעָא דְכֻמָּרַיָּא בִּלְחוֹדֵיהוֹן לָא הֲוַת לְפַרְעֹה:
@106 וִיתֵיב יִשְׂרָאֵל בְּאַרְעָא דְמִצְרַיִם בְּאַרְעָא דְגשֶׁן וְאַחֲסִינוּ בַהּ וּנְפִישׁוּ וּסְגִיאוּ לַחֲדָא:

@1 **ויגש אליו. דבר באזני אדני.** (בראשית רבה) יכנסו דברי באזניך: **ואל יחר אפך.** מכאן אתה למד שדבר אליו קשות: **כי כמוך כפרעה.** חשוב אתה בעיני כמלך, זהו פשוטו. ומדרשו - סופך ללקות עליו בצרעת כמו שלקה פרעה ע"י זקנתי שרה על לילה אחת שעכבה (בראשית רבה). דבר אחר מה פרעה גוזר ואינו מקיים מבטיח ואינו עושה אף אתה כן. וכי זוהי שימת עין שאמרה לשים עיניך עליו, דבר אחר: כי כמוך כפרעה - אם תקניטני אהרוג אותך ואת אדוניך (בראשית רבה):
@2 **אדני שאל את עבדיו.** (בראשית רבה) בתחילה בעלילה באת עלינו, למה היה לך לשאול כל אלה, ביתך היינו מבקשים, או אחותינו אתה מבקש, ואף על פי כן ונאמר אל אדוני לא כחדנו ממך דבר:
@3 **ואחיו מת.** מפני היראה היה מוציא דבר שקר מפיו, אמר - אם אומר לו שהוא קיים - ימר הביאוהו אצלי: **לבדו לאמו.** מאותו האם אין לו עוד אח:
@5 **ועזב את אביו ומת.** אם יעזוב את אביו דואגים אנו שמא ימות בדרך שהרי אמו בדרך מתה:
@12 **וקראו אסון.** (בראשית רבה) שהשטן מקטרג בשעת הסכנה: **והורדתם את שיבתי וגו'.** עכשיו כשהוא אצלי אני מתנחם בו על אמו ועל אחיו, ואם ימות זה דומה עלי ששלשתן מתו ביום:
@14 **והיה כראותו כי אין הנער ומת.** אביו מצרתו:
@15 **כי עבדך ערב את הנער.** אם תאמר למה אני נכנס לתגר יותר משאר אחי - הם כולם מבחוץ ואני נתקשרתי בקשר חזק להיות מנודה בשני עולמות:
@16 **ישב נא עבדך וגו'.** (בראשית רבה) לכל דבר אני מעולה ממנו, לגבורה, ולמלחמה, ולשמש:
@18 **ולא יכול יוסף להתאפק לכל הנצבים.** לא היה יכול לסבול שיהיו מצרים נצבים עליו ושומעים שאחיו מתביישים בהודעו להם:
@19 **וישמע בית פרעה.** ביתו של פרעה כלומר עבדיו ובני ביתו ואין זה לשון בית ממש אלא כמו בית ישראל. בית יהודה [מישנד"ה בלעז]:
@20 **נבהלו מפניו.** וכמוהו הבושה:
@21 **גשו נא אלי.** ראה אותם נסוגים לאחור, אמר עכשיו אחי נכלמים, קרא להם בלשון רכה ותחנונים והראה להם שהוא מהול (בראשית רבה):
@22 **למחיה.** להיות לכם למחיה:
@23 **כי זה שנתיים הרעב.** עברו משני הרעב:
@25 **לאב.** לחבר ולפטרון [צום בשיטצער. פאטראן בלעז ???]: **ועלו אל אבי.** ארץ ישראל גבוה מכל הארצות:
@28 **פן תורש.** דלמא תתמסכן, לשון מוריש ומעשיר:
@29 **והנה עיניכם רואות.** בכבודי ושאני אחיכם ושאני מהול ככם. ועוד כי פי המדבר אליכם בלשון הקודש (בבראשית רבה): **ועיני אחי בנימין.** (מגילה יז) השוה את כולם יחד לומר שכשם שאין לי שנאה על בנימין אחי שהרי לא היה במכירתי, כך אין בלבי שנאה עליכם:
@31 **ויפל על צוארי בנימין אחיו ויבך.** על שני מקדשות שעתידים להיות בחלקו של בנימין וסופן להיחרב:
@32 **ואחרי כן.** מאחר שראוהו בוכה ולבו שלם עמהם: דברו אחיו אתו. שמתחילה היו בושים ממנו:
@33 **והקול נשמע בית פרעה.** כמו בבית פרעה וזהו לשון בית ממש:
@34 **טענו את בעירכם.** תבואה:
@35 **ואת טוב ארץ מצרים.** ארץ גושן. ניבא ואינו יודע מה ניבא, סופה לעשותה כמצולה שאין בה דגים: **חלב הארץ.** כל חלב לשון מיטב הוא:
@36 **ואתה צויתה.** מפי לומר להם: **זאת עשו.** כך אמור להם שברשותי הוא:
@40 **שלח כזאת.** כחשבון הזה ומהו החשבון י' חמורים וגו'. (רצונו שמלת כזאת המיותרת ובכ''ף הדמיון מורה על כי מעולם לא שלח לו י' חמורים וי' אתונות, רק הכי קאמר קרא. בשם הגאון מהרש"ל): **מטוב מצרים.** מצינו בגמרא ששלח לו יין ישן שדעת זקנים נוחה הימנו. ומדרש אגדה גריסין של פול: **בר ולחם.** כתרגומו: **ומזון.** לפתן (כך גירסאת רא"ם):
@41 **אל תרגזו בדרך.** אל תתעסקו בדבר הלכה שלא תרגז עליכם הדרך. דבר אחר - אל תפסעו פסיעה גסה ותכנסו בחימה לעיר, ולפי פשוטו של מקרא יש לומר - לפי שהיו נכלמים - היה דואג שמא יריבו בדרך על דבר מכירתו להתווכח זה עם זה ולומר על ידך נמכר, אתה ספרת לשון הרע עליו וגרמת לנו לשנאתו:
@43 **וכי הוא מושל.** ואשר הוא מושל: **ויפג לבו.** נחלף לבו והלך מלהאמין, לא היה לבו פונה אל הדברים, לשון מפיגין טעמן בלשון משנה וכמו (איכה ג) מאין הפוגות (ירמיה מח ???) וריחו לא נמר מתרגמינן וריחיא לא פג:
@44 **את כל דברי יוסף.** סימן מסר להם במה שהיה עוסק כשפירש ממנו בפרשת עגלה ערופה, זהו שנאמר וירא את העגלות אשר שלח יוסף ולא נאמר אשר שלח פרעה: **ותחי רוח יעקב.** שרתה עליו שכינה שפירשה ממנו:
@45 **רב עוד.** רב לי עוד שמחה וחדוה הואיל ועוד יוסף בני חי:
@46 **בארה שבע.** כמו לבאר שבע, ה"א בסוף תיבה במקום למ"ד בתחילתה: **לאלוהי אביו יצחק.** חייב אדם בכבוד אביו יותר מבכבוד זקנו לפיכך תלה ביצחק ולא באברהם:
@47 **יעקב יעקב.** לשון חיבה:
@48 **אל תירא מרדה מצרימה.** לפי שהיה מיצר על שנזקק לצאת לחוצה לארץ:
@49 **ואנכי אעלך.** הבטיחו להיות נקבר בארץ:
@51 **אשר רכשו בארץ כנען.** אבל מה שרכש בפדן ארם נתן הכל לעשו בשביל חלקו במערת המכפלה, אמר נכסי חוצה לארץ אינן כדאי לי וזהו אשר כריתי לי, העמיד לו צבורין של זהב וכסף כמין כרי ואמר לו טול את אלו:
@52 **ובנות בניו.** סרח בת אשר, ויוכבד בת לוי:
@53 **הבאים מצרימה.** על שם השעה קורא להם הכתוב באים. ואין לתמוה על אשר לא כתב אשר באו:
@55 **בן הכנענית.** בן דינה שנבעלה לכנעני ,כשהרגו את שכם לא הייתה דינה רוצה לצאת עד שנשבע לה שמעון שישאנה (בראשית רבה):
@60 **אלה בני לאה ואת דינה בתו.** הזכרים תלה בלאה והנקבות תלה ביעקב ללמדך אשה מזרעת תחלה יולדת זכר, איש מזריע תחלה יולדת נקבה: **שלשים ושלש.** ובפרטן אי אתה מוצא אלא שלשים ושנים, אלא זו יוכבד שנולדה בין החומות בכניסתן לעיר שנאמר אשר ילדה אותה ללוי במצרים, לידתה במצרים ואין הורתה במצרים:
@64 **בני רחל אשת יעקב.** ובכולן לא נאמר בהן אשת אלא שהיתה עיקרו של בית:
@71 **כל הנפש הבאה ליעקב.** שיצאו מארץ כנען לבוא למצרים. ואין הבאה זו לשון עבר, אלא לשון הווה, כמו (אסתר ב) בערב היא באה וכמו והנה רחל בתו באה עם הצאן, לפיכך טעמו למטה באל"ף, לפי שכשיצאו לבוא מארץ כנען לא היו אלא שישים ושש. והשני כל הנפש לבית יעקב הבאה מצרימה שבעים הוא לשון עבר לפיכך טעמו למעלה בבי"ת לפי שמשבאו שם היו שבעים שמצאו שם יוסף ושני בניו ונתוספה להם יוכבד בין החומות. (ועיין בביאור לת"י ומשם תמצא להרוות צמאונך ברש"י) ולדברי האומר תאומות נולדו עם השבטים צריכים אנו לומר שמתו לפני ירידתן למצרים שהרי לא נמנו כאן. מצאתי בויקרא רבה עשו שש נפשות היו לו והכתוב קורא אותן נפשות ביתו לשון רבים, לפי שהיו עובדין לאלהות הרבה, יעקב שבעים היו לו והכתוב קורא אותן נפש, לפי שהיו עובדים לאל אחד:
@73 **להורות לפניו.** כתרגומו לפנות לו מקום ולהורות האיך יתיישב בה: **לפניו.** קודם שיגיע לשם.ומדרש אגדה: להורות לפניו לתקן לו בית תלמוד שמשם תצא הוראה:
@74 **ויאסור יוסף מרכבתו.** הוא עצמו אסר את הסוסים למרכבה להזדרז לכבוד אביו: **וירא אליו.** יוסף נראה אל אביו: **ויבך על צואריו עוד.** לשון הרבות בכיה. וכן (איוב לד) כי לא על איש ישים, עוד לשון רבוי הוא, אינו שם עליו עלילות נוספות על חטאיו, אף כאן הרבה והוסיף בבכי יותר על הרגיל אבל יעקב לא נפל על צוארי יוסף ולא נשקו. ואמרו רבותינו שהיה קורא את שמע:
@75 **אמותה הפעם.** פשוטו כתרגומו ומדרשו - סבור הייתי למות שתי מיתות בעולם הזה ובעולם הבא, שנסתלקה שכינה ממני, והייתי אומר שיתבעני הקב"ה מיתתך, עכשיו שעודך חי לא אמות אלא פעם אחת:
@76 **ואמרה אליו אחי וגו'.** ועוד אומר לו (פסוק לב) והאנשים רועי צאן וגו':
@79 **בעבור תשבו בארץ גשן.** והיא צריכה לכם שהיא ארץ מרעה, וכשתאמרו לו שאין אתם בקיאין במלאכה אחרת ירחיקכם מעליו ויושיבכם שם: **כי תועבת מצרים וגו'.** לפי שהם להם אלהות.
@81 **ומקצה אחיו.** מן הפחותים שבהם לגבורה שאין נראים גיבורים, שאם יראה אותם גיבורים יעשה אותם אנשי מלחמתו. ואלה הם ראובן שמעון לוי יששכר ובנימין, אותם שלא כפל משה שמותם כשברכם, אבל שמות הגיבורים כפל, וזאת ליהודה שמע ה' קול יהודה, ולגד אמר ברוך מרחיב גד. ולנפתלי אמר נפתלי. ולדן אמר דן. וכן לזבולן, וכן לאשר זה לשון בראשית רבה שהיא אגדת ארץ ישראל אבל בגמרא בבלית שלנו (בבא קמא צ''ב) מצינו שאותם שכפל משה שמותם הם החלשים ואותן הביא לפני פרעה, ויהודה שהוכפל שמו לא הוכפל משום חלשות, אלא טעם יש בדבר כדאיתא בבבא קמא ובברייתא דספרי שנינו בה בוזאת הברכה כמו בגמרא שלנו:
@85 **אנשי חיל.** בקיאין באומנותן לרעות צאן: **על אשר לי.** על צאן שלי:
@86 **ויברך יעקב.** היא שאילת שלום כדרך כל הנראים לפני המלכים לפרקים, שלידי"ר בלע"ז [גריסען]:
@88 **שני מגורי.** ימי גרותי כל ימי הייתי גר בארץ: **ולא השיגו.** בטובה:
@89 **ויברך יעקב.** כדרך כל הנפטרים מלפני שרים מברכים אותם ונוטלים רשות ומה ברכה ברכו שיעלה נילוס לרגליו לפי שאין מצרים שותה מי גשמים אלא נילוס עולה ומשקה ומברכתו של יעקב ואילך היה פרעה בא אל נילוס והוא עולה לקראתו ומשקה את הארץ [תנחומא]:
@90 **רעמסס.** מארץ גושן היא:
@91 **לפי הטף.** לפי הצריך לכל בני ביתם:
@92 **ולחם אין בכל הארץ.** חוזר לענין הראשון לתחלת שני הרעב: **ותלה.** כמו ותלאה לשון עייפות כתרגומו ודומה לו (משלי כו) כמתלהלה היורה זיקים:
@94 **אפס.** כתרגומו שלים:
@97 **בשנה השנית.** שנית לשני הרעב: **כי אם תם הכסף וגו'.** כי אשר תם הכסף והמקנה ובא הכל אל יד אדוני: **בלתי אם גויתנו.** כמו אם לא גויתנו:
@98 **ותן זרע.** לזרוע האדמה ואע"פ שאמר יוסף ועוד חמש שנים אשר אין חריש וקציר מכיון שבא יעקב למצרים באה ברכה לרגליו והתחילו לזרוע וכלה הרעב וכן שנינו בתוספתא דסוטה: **לא תשם - לא תהא שממה.** לא תבור לשון שדה בור שאינו חרוש:
@99 **ותהי הארץ לפרעה.** קנויה לו:
@100 **ואת העם העביר.** יוסף מעיר לעיר לזכרון שאין להם עוד חלק בארץ והושיב של עיר זו בחברתה, ולא הוצרך הכתוב לכתוב זאת אלא להודיעך שבחו של יוסף שנתכוין להסיר חרפה מעל אחיו שלא יהיו קורין אותם גולים (חולין ס): **מקצה גבול מצרים וגו'.** כן עשה לכל הערים אשר במלכות מצרים מקצה גבולה ועד קצה גבולה:
@101 **הכהנים.** הכומרים כל לשון כהן משרת לאלהות הוא חוץ מאותן שהם לשון גדולה כמו כהן מדין כהן און: **חוק לכהנים.** חק כך וכך לחם ליום:
@102 **הא.** כמו הנה כמו (יחזקאל טז) וגם אני הא דרכך בראש נתתי:
@104 **נמצא חן.** לעשות לנו זאת כמו שאמרת: **והיינו עבדים לפרעה.** להעלות לו המס הזה בכל שנה לחק שלא יעבור:
@106 **וישב ישראל בארץ מצרים.** והיכן בארץ גושן שהיא מארץ מצרים: **ויאחזו בה.** לשון אחוזה:

@1 **ויגש אליו**. צל''ד למה הוצרך לומר **ויגש** אחר שקרוב אליו היה ומדבר עמו עד עתה, ורז''ל דרשו יעויין שם דבריהם (ב''ר פ' צ''ב) וצל''ד פשט הכתוב. עוד לא היה צריך לומר תיבת **אליו** ומובן הדבר. עוד צל''ד אומרו **בי אדוני** לא נודע הריצוי למה, ואם לבל יחר אפו היה לו לאומרו סמוך לואל יחר וגו'. עוד צל''ד אומרו **באזני אדוני**, ורז''ל (שם) אמרו שיכנסו דבריו באזניו וזה דרך דרש. עוד צל''ד כוונת אומרו **כי כמוך** כי לא נודע נתינת טעם זה להיכן חוזרת ואדרבא לצד שהוא גדול כפרעה יקפיד על מיעוט הנהגת כבוד וגדולה:
@1 **אכן** פשט הכתוב הוא כי דבר ידוע הוא כי מנהג המלכים ישבו לפניהם גדולי המלכות ושריהם ויועציהם והיה אם בא איש על דבר משפט או דבר מאת המלך לא יעמוד בהפסק בין המלך ושריו היושבים ראשונה במלכות וחוץ לעגול יעמוד ושם ידבר, וכמו כן היה מדבר יהודה עד עתה ואח''כ ויגש אליו פי' שנכנס לפנים ממחיצתו ועמד בין המלך ובין השרים כדי שלא ישמעו דבריו לזולת המלך. ועיין מה שכתב מהר''מ אלשקר (בתשובותיו ס' צ''ג) בשינוי תיבת לו לתיבת אליו. וחילה פני המלך שיתרצה לו לדבר ביחוד אליו והוא אומרו **בי אדוני ידבר נא עבדך דבר באזני אדוני** באין שומע זולתך וזה לא יתכן אם לא באזניו, וחילה פניו שלא ימהר להתכעם על אשר שואל כזה ואינו מהמוסר, והוא אומרו **ואל יחר אפך בעבדך** פי' כי דרך זה יעשוהו גדולים השוים בגדר גדולה זה לזה לא עבד לאדונו והוא אומרו **בעבדך** וטעם הדבר כי כמוך כפרעה פי' ע''ד מעשה שהובא בגמרא (ע''ז י:) של קטיעא בר שלום שאמרו לו נצחת למלכא וכל דנצח למלכא וכו' ע''כ, לזה אם היה נוצח יהודה ליוסף בפני השומעים יכנס בסכנת מות מדין נוצח למלך, ולבל יטעון כי המלך הוא פרעה לזה אמר **כי כמוך כפרעה** ודינם שוה, אשר ע''כ מבקש על נפשו לדבר באזנו ובזה הגם שינצחהו בטענות אין בזוי למלך ולא יכנס בדין נוצח למלך שחייב כיון שהוא בינו לבין המלך:
@1 **עוד** ירצה **כי כמוך** וגו' ע''ד אומרו (משלי כ''א) לב מלך ביד ה' ואם ידבר בדרך שתשמע מלתו לכל הנמצאים שם יעשו למלך הפך דעתו ורצונו של מלך ונמצא המלך עושה דבר שלא כאשר שם ה' בלבו ויעוותו יועציו את לבו לזה אל יחר אפו על כניסתו לפנים ממחיצתו לדבר באזני המלך. גם בזה הגיד לו כי הוא איש חסד ודוקא רואי פניו נכנסו בחשד דבר תקלה ב''מ:
@1 **ובדרך** דרש יתבאר אומרו **ויגש אליו** ע''ד אומרו (משלי כ''ז) כמים הפנים לפנים כן לב האדם לאדם ולזה נתחכם יהודה להטות לב יוסף עליו לרחמים והקריב דעתו ורצונו אליו לאהבו ולחבבו כדי שתתקרב דעתו של יוסף אליו לקבל דבריו ופיוסו, והוכרח לעשות כן לצד שמן הטבע לא יחבבו בני יעקב עע''ז כי (תהלים קכ''ה) לא ינוח שבט הרשע על גורל הצדיקים וממזג נפשם לשנוא אשר בשר חמורים בשרם, לזה הוצרך לפי שעה להפך המוטבע ולהגישו בלבבו ולהשיבו בתוואני דליביה:
@1 **עוד** ירצה כי לא נגש יהודה לדבר אלא למה שאליו פי' למה שהבינו כי הגזירה לא מאת ה' באה כמו שפירשתי בפרשה הקודמת בפסוק (י''ז) חלילה, וכיון שאין הענין בא אלא מיוסף ואליו הם הדברים מסורים לאשר יחפוץ עשות לזה ויגש:
@1 **עוד** ירצה לומר כי לטובתו של יוסף הוא נגש כי בכל פרטי הנאות אשר יעשה העבד יהודה יעשה יותר מבנימין והוא אומרו **ויגש אליו** פירוש לטעון טענה שהיא לטובת המלך והוא (ל''ג) ישב נא וגו':
@1 **עוד** ירצה **באומרו אליו** לבל יאמר האומר איך סותר יהודה דברי עצמו הננו עבדים גם אנחנו, (ט''ז) לזה אמר כי מה שנגש לדבר דברים האמורים בענין ישב נא עבדך וגו' והנער יעל עם אחיו הוא אליו פירוש לדברי יוסף הוא שמצא ליכנס לדבר כדברים האלה שאמר חלילה וגו' אבל למה שאמר יהודה אין מענה בלשונו לדבר מה שאמר בענין:
@1 **ואומרו בי אדני** נתכוין לג' דברים, הא' לבל יאמר אליו יוסף למה ידבר הוא לבד מכולם, ומה גם במה שקדם שהכיר יוסף כי ראובן הבכור דכתיב (מ''ג ל''ג) וישבו לפניו הבכור וגו' ואם כן יאמר למה ידבר כל כך הוא ולא אחיו לזה אמר בי נוגע הדבר כמו שביאר לו לבסוף. ולהיות שחש לו להתכעס קודם הגעת הדבר אליו לזה קדם תכף והודיעו, והוא אומרו בי נוגע הדבר אדוני, והב' שנתכוין לטעון טענה הנשמעת להציל בנימין והוא **בי אדוני** פי' אני גנבתי הגביע והנחתיו באמתחת בנימין ומעתה שורת הדין תתן כי הוא ילכד כי בנימין מכחיש ויהודה מודה הוא יהיה עבד, הג' רמז הכתוב כי השררה אליו היא נתונה, וזה שיעור הדברים בי תלוי כינוי תיבת אדוני כי הוא המלך, ואו' **ידבר נא** פירוש ידבר עתה בכינוי עבדות לפי שעה אבל אין הדבר עומד כן כי יהודה הוא המלך וכסאו יכון עולם:
@1 **עוד** ירמוז הכתוב באומרו **בי אדוני** פירוש באמצעותי השגת זה כי הוא הסובב ליוסף אדנות שאמר (ל''ז כ''ז) לכו ונמכרנו לישמעאלים שמזה נתגלגל הדבר והשיג יוסף האדנות:
@2 **אדוני שאל וגו' לאמר**. טעם הצעת הדברים, לומר כי לצד ההכרח לקחו בנימין מאת אביו ואם לא יראהו עמהם ימות אביו מדאגתו. והתחיל לומר **אדני שאל את עבדיו** פירוש לא היתה שאלת אדם לכיוצא בו שיוכל למנוע התשובה ממנו אלא כי היתה מאת אדוני לעבדיו וכיון שכן בהכרח **לאמר** לך אמיתתן של דברים. עוד ירצה באומרו **לאמר** כי מלבד השאלה עשית לנו דבר המחייב אותנו לאמר לך בלא העלמה כי עשה אותם כמרגלים והוצרכו לאמת דבריהם כמשפט בדיקת האנשים הנחשדים ברוגל שנבדקים בכל הפרטים הגם שאינן נוגעים בענין הריגול ואם העלם יעלימו דבר ינתנו בקולר, לזה הכריחם לאמר:
@4 **ותאמר אל עבדיך הורידוהו**. פירוש לא הספיק לך לאמת הדבר בדברינו או על ידי בירור אחר זולת להורידו אליך ותוסף לחזק עלינו לבל נראה פניך זולתו והודענו הדבר לאבינו ולא הועיל לשלוח אותו עד אשר כלתה התבואה וגו' והוצרכנו להורידו:
@11 **אך טרוף וגו'**. רמז באומרו **אך** כי מעט טרוף טורף כי אינו לא בצרת עבדות ולא בצרת משמר, ולזה גמר אומר **ולא ראיתיו עד הנה** הרי זה מגיד כי ישנו בנמצא אלא שעדיין לא ראהו עד עתה:
@11 **עוד** ירצה באומרו **אך טרוף** וגו' פירוש אך מיעוט דוקא בטריפות אבל במה שאמר (שם ל''ג) חיה רעה אכלתהו שאמרו ז''ל (ב''ר פפ''ד) שנתכוין אל אשת פוטיפר בזה אין מיעוט כי כבר בעונות היה מה שהיה שגרמה לו לאבד י' בנים שעתיד היה להעמיד י''ב שבטים כאומרם ז''ל (סוטה לו:) ובאמצעות הרשעה נשרו ממנו י' טיפות ולא יצאו ממנו אלא ב':
@16 **ישב נא עבדך**. והגם שאמר (מ''ג ט') והצגתיו לפניך, שלוחו של אדם כמותו:
@17 **כי איך אעלה וגו'**. פירוש בלא טעם האמור שאמר וחטאתי וגו' איך אעלה וגו'. ועוד אולי שנותן טעם למה שאמר בתחלה (ט''ז) הננו עבדים גם אנחנו וגו', כי איך אעלה וגו' פן אראה ברע, וכשלא יעלו כולן לא יראה וגו':
@17 **עוד** יכוין להשיב לטענת אשה חכמה ששלח יואב לדוד (ש''ב י''ד) כי קמה המשפחה להרוג את מכה אחיו ותמיתהו בנפש אחיו וגו', והנה הוא הנדון שלפנינו כי כשיגיד יהודה לאביו כי אנוס הוא ואינו יכול להציל בנימין מיד המלך פשיטא שלא יתאכזר יעקב וישכל גם שניהם יהודה ובנימין ויתיר לנידויו של יהודה, לזה אמר טענה שנית כי איך אעלה וגו' כי חושש לסכנת מות אביו:
@18 **ולא יכול יוסף להתאפק**. פירוש שלא עצר כח להמתין עד שיצאו כל הנצבים מעצמן וקרא בקול גדול הוציאו כל איש פירוש במהרה לא שיאמרו להם לצאת כי כשיצאו מעצמן יצאו במיתון ולא סבל אורך זמן ההוצאה, ואמר **ולא עמד** פי' לא נתעכב איש אלא במהרה תיכף יצאו יחד:
@18 **בהתודע יוסף וגו'**. פירוש בשביל התודעותו אל אחיו פירוש הכרת דבר כדי שיכירו ויצדיקו כי הוא יוסף ודבר זה צריך להזכירם במכירתו ולא רצה לזלזל באחיו שיחזיקו אותם בדבר נבלה כזו למכור אחיהם, ואמר בסמוך **ויתן את קולו בבכי וישמעו מצרים** וכו' הרי זה מגיד כי מה שמנע הזולת בהתודעו לאחיו לא לצדו כי הוא קרא בקול ושמעו כל העיר את הדבר אלא לצד בושת אחיו הוא שעשה מטעם הנזכר:
@21 **ויאמר יוסף וגו' גשו נא וגו'**. טעם ההגשה, לצד שרצה לומר להם ענין המכירה לזה לא רצה לומר להם אלא בלחישה, לזה אמר גשו ואחר שנגשו אמר להם וגו' אשר מכרתם אותי וגו', והגם שאמר הוציאו כל איש וגו' ולא עמד שם אדם אף על פי כן חש לאזנים לקיר ודבר באזניהם:
@21 **אני יוסף אחיכם וגו'**. טעם שחזר פעם ב' **אני יוסף**, לצד שראה שלא ענוהו חשש לב' דברים. האחד שפחדו ממנו ולא יכלו להשיב כבושת גנב כי ימצא, והב' שלא האמינוהו שהוא יוסף, לזה אמר כנגד צד היראה שאתם יראים ונבהלתם לא תחושו לדבר כי אני יוסף אחיכם פירוש מתנהג עמכם במדת האחוה וכאלו לא היה הדבר ההוא, גם סמך לומר **אחיכם אשר מכרתם** לומר שאפילו בזמן המכר לא כהתה עין האחוה ממני, וכנגד צד הצדקת הדבר שהוא יוסף אמר להם דבר שבו יצדיקו בסימן מובהק כי הוא זה באומרו **אשר מכרתם אותי מצרימה** ודבר זה לא ידעו אדם ואפילו נביא (ילקוט קמ''ב) אם לא שתאמר ודאי גמור כי הוא זה יוסף:
@22 **ועתה אל תעצבו וגו'**. צריך לדעת א' אומרו ועתה מה בא לשלול. ב' למה כפל לומר **אל תעצבו ואל יחר**, ועוד הם ב' דברים הפכים העצבון יורה על שברון הלב, וחרון אף יגיד על הגאוה. עוד צריך לדעת למה דקדק לומר תיבת **הנה**:
@22 **אכן** פי' של דברי' הוא על זה הדרך יודע אני כי אתם נעצבים על המכר וכמו שגילו דעתם באומרם (מ''ב) אבל אשמים אנחנו, גם לפי המדרש (ב''ר פ' צ''א) שאמרו שירדו לפדותו בדמים יקרים, לזה אמר להם **ועתה** פירוש כיון שמבוקשם מצוי להם בהודעה זו תסירו העצבון, ונתכוין גם כן בזה לרמוז להם ולהודיעם כי יודע בהם שדעתם קרובה אצלו והם נעצבים עליו עד עתה ובזה יצדיקו כי לבו נכון עמם. ואומרו **אל יחר בעיניכם** פירוש לטעם שמכרתם אותי הנה שגרמתם לעצמיכם כל התגלגלות הענינים ההשתחויות אשר בשבילם נתחכמתם למכור דכתיב (וישב לז) ונראה מה יהיו וגו' ודבר זה יסובב הכעם כאדם שבא לתקן דבר ונמצא מקלקל ויחר אפו על אשר גרם לעצמו, ונתן טעם לזה כי אדרבא מעשיהם גרמו להם טובה גדולה כי למחיה שלחני אלהים לפניכם כי זה וגו' לשום לכם שארית וגו' ומעתה לא יחר בעיניכם על הדבר:
@25 **ועתה לא אתם וגו'**. פי' לתת טעם להסיר מלבם חשש השנאה לבל יחשבו כי יוסף ישטום אותם וישנאם על אשר נתאכזרו עליו ויהיה בעיניהם דבר רחוק שיהיה לב יוסף נכון עמם, לזה אמר להם הן אמת כי בשעת מעשה אשר מכרוהו היו הדברים זרים בעיניו איך יהיה כל האכזריות בלב אחים על אחיהם וראוים הם להיות שנואים אצלו:
@25 **אכן** עתה אחר ראותו כל הנמשך מירידתו מצרים ידע כי המעשה היה מאת ה' והם שליחותו יתברך עשו ולא שליחות עצמם ובזה אין מקום לשמור להם איבה ולא להרחיק מדת האחוה מהם:
@25 **ואולי** כי בזה היה להם פנים לעמוד לפני אביהם כשנגלה הדבר כי הם הגורמים לו אבל ובכי כ''ב שנה ועשו המעשה המופלא במכר אחיהם ורואני שגם בוש לא יבושו מאביהם, והיה נראה לומר כי יעקב לא ידע גוף המעשה, וזה דרך רחוק, כי פשיטא שלא ימנע מחקור זאת היאך נתגלגלו הדברים עד שירד יוסף למצרים וגם מעשה כתונת הפסים המובא אליו מוטבל בדם, אלא ודאי כי בטענת לא אתם שלחתם וגו' שאמר יוסף הוכר הדבר כי מאת ה' היתה זאת ואין להרהר אחר מדותיו, והוא אומרם ז''ל (ב''ר פ' פ''ז) ראוי היה יעקב לירד בשלשלאות וכו':
@32 **ויבך עליהם ואחרי כן דברו וגו'**. פירוש אחר שראו שבכה עליהם אז סמך לבם ודברו אתו כי כל הדברים שהיה אומר אפשר שהיה אומר להם כן להסיר מהם הבושה ולעולם לבבו ימר עליהם מצד המעשה. אכן כשראו שחבק אותם ובכה על פרידתם הכירו במדת טובו כי אח נאמן הוא ודברו אתו. והגם שבכה מקודם אין הוכחה מזה כי אפשר זכר צרתו ובכה עליה מה שאין כן בכי זה שבכה עליהם. גם בכי הראשון יש מקום לתלות שבכה על פרידת בנימין מה שאין כן כשבכה עליהם בפרטות זה יגיד אחוה בלב:
@33 **והקל נשמע וגו' לאמר וגו'**. פירוש להיות שכבר הודיע הכתוב למעלה כי שמעו מצרים ובית פרעה בכי יוסף דכתיב (פסוק ב') וישמעו מצרים וגו' עתה מודיע הכתוב כי הקול ששמעו בית פרעה האמור למעלה ולא ידעו מה הוא ועל מה היה ועתה אמרו להם כי זה היה לצד ביאת אחיו של יוסף:
@33 **וייטב בעיני וגו'**. פירוש כי קודם היתה להם חרפה כי עבד מולך ובביאת אחיו וייטב בעיניו כי הוכר שאינו עבד:
@34 **זאת עשו**. פירוש דבר זה אינכם צריכין לעשותו ברשות אבל העגלות אינכם יכולין לעשות כי אם ברשות, ואפילו רשות מיוסף לא תועיל אלא צריך שיאמר שהוא עושה ברשות פרעה, והוא אומרו **ואתה צויתה** וגו', וכן הוא אומר **ויתן להם** וגו' **עגלות על פי פרעה**, וזה היה מנימוסי מצרים:
@34 **עוד** ירצה באומרו **זאת עשו** פירוש כי הוא בצו להם לא שמתרצה לבד לעשות עמהם חסד אלא שהוא חפץ בדבר ואומר **זאת עשו**. ומה' יצא הדבר כדי שירדו אבותינו מצרים:
@40 **ולאביו שלח כזאת וגו'**. טעם אומרו **כזאת** ולא הספיק המפורש. להיות שאמר נושאים מטוב מצרים ולא נודע מה הוא טוב מצרים לזה הקדים לומר כזאת לומר כמין המוזכר בסמוך שמלות וכלי כסף מהמובחר הנמצא ממין זה במצרים. ולדברי רז''ל (מגילה טז:) שאמרו טוב מצרים יין ישן ולמ''ד (ב''ר פ' צ''ד) גריסין של פול יהיה הכתוב חסר וא''ו וכאלו אמר כזאת ועשרה וגו' והכוונה באומרו כזאת כמו שפירשנו ועוד עשרה וגו':
@40 **ועשר וגו' לאביו וגו'**. טעם שחזר לומר פעם ב' **לאביו**, נתכוין לומר כי לא שלחם אליו בגדר שליחות הסמוכה לה אלא נתנם לאחיו ואמר להם שהם לאביו לדרך:
@41 **וישלח את אחיו**. פירוש כולן ובנימין עמהם, וכן הוא אומר בדברי יוסף (פסוק ט') מהרו ועלו אל אבי וגו' והנה עיניכם וגו' ועיני אחי בנימין הרי כי מצדיק הדברים בלב יעקב מעדות בנימין הרואה, ומעתה לא נתלה לומר טעם שהיו עצמותיו של יהודה מתגלגלין הוא לצד שלא קיים דברו אלא לצד שנידוי על תנאי צריך התרה כאומרם ז''ל (מכות יא:):
@43 **ויגידו לו לאמר**. טעם אומרו **ויגידו** שהלשון יגיד על הקושי. להיות שאמרו דברים שהם קשים אצלם לאומרם כי סוף סוף תגלה רעתם אצלו אשר עשו ואשר גרמו לאביהם כל הצער והבכי, וכפי זה אמר ויגידו למה שנוגע להם. או לצד שבשורה זו גורמת ירידת מצרים והשעבוד הקשה אשר מררו את חיי ישראל במצרים, וכן תמצא שהיה ירא מירידת מצרים עד שאמר לו ה' (מ''ו ג') אל תירא מרדה מצרימה:
@43 **וטעם** אומרו **לאמר** נתחכמו לבשרו בדרך שלא יסתכן יעקב, כי דבר ידוע הוא כי בשורה טובה כשתהיה על יגון ומה גם כשתהיה מופלאת לרוב השמחה יסוכן האדם ויחלש ויגוע פתע פתאום, אשר על כן חששו על הדבר ונתחכמו לדבר אליו בדרך שלא תארע תקלה, והוא אומרו **ויגידו לו לאמר** פירוש אמרו לו שיש להם בשורה לאמר לו ובזה תתרחב נפשו וישמח לבו ואחר כך אמרו לו **עוד יוסף חי** ולא נסתכן כי הוכן בלבו הכנת קבלת בשורה טובה. או יתבאר שיעור הכתוב על זה הדרך **ויגידו לו לאמר עוד** פירוש מלבד שבאו שלמים שמעון ובנימין עמהם עוד יש להם לאמר לו, ואחר שהכין דעתו לדבר טוב הודיעוהו יוסף חי, והוסיפו עוד לומר **וכי הוא מושל** בשורה אחר בשורה לטעם הנזכר:
@43 **ראיתי** לתת לב בענין יוסף איך לא חש על צער אביו כמה שנים, והן אמת בימי עבדותו נוכל לומר כי עשה ולא הצליח אלא אחר שעלה לגדולה למה לא כתב אגרת לאביו להפיג צערו כי יודע היה יוסף גודל הפלגת חיבת יעקב בו ויתאבל עליו ימים רבים ולמה לא שלח לבשרו ותגדל עוד הקושיא על ימי הרעב שהיו עוברים ושבים מארץ מצרים לארץ כנען ולא חש על צערו ועוד מי התיר לו אחר שבאו אחיו להאריך לו ימי צרה שלא להודיעו תיכף ומיד:
@43 **והן** אמת כי למה שנתגלגל בעניינים שגזר הגוזר רבים הם שהיו צריכין להיות כן הא' לשלם ליעקב כ''ב שנים שלא שמש אביו וכמו כן היה הוא בצער כ''ב שנים, וגם למספר רד''ו שגזר ה' שיהיו במצרים, וגם לירד יעקב בכבוד גדול מה שלא היה כן אם היה יורד קודם וכמה פרטים שנמשכו, אלא לצד יוסף צריכין לתת טעם לדבר:
@43 **ונראה** כי טעמו של יוסף טעם לשבח והוא כי מעת ירידתו למצרים עד עת בוא דברו יתברך והוציאו מבית האסורים למלוך אין סיפק בידו להודיע לאביו ואפילו שיונח שהיה סיפק בידו חש על נפשו שידעו אחיו בדבר ולצד בושתם וכלימתם מאביהם ימסרו עצמם עליו לאבדו מן העולם לבל תגיע להם בושת מאביהם וגם אפשר כי יקללם וימית כולם ומצד זה יבקשו לקעקעו מהעולם לזה חש על נפשו שידעו אחיו בדבר וימנע מבא בדמי נפשו ואחר צאתו ממאסר ונעשה שר גדול והלכה לה חששה ראשונה אף על פי כן נמנע מהודיע לאביו והוא על דרך אומרם ז''ל (ב''ק נ''ט.) מוטב שיפיל אדם עצמו לכבשן האש ואל ילבין פני חבירו וחש על כבוד האחים מלביישם לפני יעקב ויצחק וכל זרע יעקב וסבל שישאר אביו בצערו מלביישם ועוד אף כי אחר שעלה לגדולה חשב יוסף בלבם מיחוש ההשטמה ממנו ויתיעצו עליו לעוקרו מהעולם, וכמו כן תמצא שאמרו ז''ל (תנחומא) שרצו לעוקרו אפילו בימי גדולתו ובא גבריאל ופזרן, והגם שאמרו ז''ל (ב''ר פ' צ''א) שירדו אחריו למצרים לפדותו בדמים יקרים ישתנה הדבר אם יפדוהו הם שאז יכיר באחוותם וזולת זה עברתו שמרה נצח ולא ישכח את אשר עשו לו ויקדמו הם להורגו, הנך רואה כי אם היה מודיע מקודם ליעקב כי הוא חי היו מתאזרים ובאים ומאבדים אותו מהעולם, וגם אחר שבאו לפניו בשנת רעב לא רצה לגלות עצמו תיכף להם ולא לאביו כי עודנו בסכנת מיחוש כנזכר עד שנתחכם והאכילם והשקם ונתן להם דמים והראה להם כי הוא עמהם בלב שלם. גם נגלה הדבר כי מה' יצא וידעו ודאי כי לא שומר הוא להם איבה, וגם באמצעות כן הוסרה בושה מאביהם כי יאמרו אליו כי כן גזר הגוזר וכמו שפירשתי בפסוק (ח') לא אתם וגו' ואז גילה להם ואף על פי כן הוצרך ה' לשלוח מלאך להצילו מידם כמאמרם ז''ל. (תנחומא ויגש) ואולי כי הוא יוסף לא ידע בדבר. או אפשר שידע שהצילו מלאך ואין להקשות עליו שהיה לו להודיע לאביו קודם ולא יחוש אל האחים כי המלאך הגואל אותו עתה יגאלנו גם כן קודם כי אין סומכין על הנס, ובזה אין להאשימו ליוסף על הדבר ונכון:
@48 **אל תירא וגו' כי לגוי וגו'**. צריך לדעת מה הוא המורא שהיה ליעקב בירידת מצרים, ואם מורא הגלות אם כן מה הוא כוונת ה' באומרו אל תירא במה מסיר ממנו המורא, ואם כוונתו שלא יהיה גלות שם, מצינו שלא כן היה כי שם נשתעבדו בניו בעינוי ועבודה קשה. עוד קשה אומרו **כי לגוי גדול** מה נתינת טעם זה להסרת המורא, עוד צריך לדעת אומרו **לגוי גדול אשימך שם** ולמה לא ישימהו גוי גדול במקום אחר. עוד צריך לדעת למה אמר **לגוי** ולא אמר כי גוי גדול אשימך וגו':
@48 **אכן** כוונת הכתוב הוא לצד מה שקדם מההודעה להאבות כי נגזרה גזירת הגלות עליהם דכתיב (בראשית טו) כי גר יהי' זרעך וגו' ומן הסתם יגיד אברהם לבניו, וכן הוא מפורש בדבריהם ז''ל (ב''ר פ' פ''ב) אשר על כן כשראה יעקב שבר במצרים כי שם יסבלו בניו הגלות לזה כשירד ירא לנפשו כי יתחיל הגלות ממנו, גם ירא היה שמא יקבר שם בארץ טמאה, אשר על כן נגלה אליו ה' ואמר לו אנכי אלהי אביך נתכוון באמירה זו כי כשם שאביך לא טעם טעם שעבוד ועינוי כמו כן אתה אל תירא הגם שאתה יורד מצרימה, ולצד שיחשוב יעקב לחזור ולעלות ממצרים כשימצא שעת הכושר והוא אחר עבור שנת רעב והבטחתו יתברך שאומר לו אל תירא היא על זמן מועט שיהיה שם, לזה גמר אומר **כי לגוי גדול אשימך שם** פירוש רוצה אני לשום אותך שם לצורך גוי גדול. ולהשכיל על דבר אקדים אמרי קדוש הוא הרשב''י ואנשי סודו (ליקוטי תורה מקץ) שאמרו כי טעם הגליות הוא לברר חלקי הקדושה המפוזרים בענפי הקליפה וכי במצרים להיותה מלאה גלולים ושם תוקף הטומאה שם הוא שביית חלקי הקדושה הרבים והעצומים. כי לערך גודל הטומאה יהיה בקרבה חלקי הקדושה, וזה היה מיום שחטא אדם הראשון שלטה שפחה רעה בניצוצי הקדושה, ועיני כל ישראל על זה בכל הגליות ובפרט בגלות מצרים, והוסיפו לומר ז''ל (שם וישב) כי עם היוצא מארץ מצרים העומד על הר סיני הוא העם שהיה שבוי בתוך קליפת מצרים ואליו אמר משה נביא ה' (דברים ד' ח') ומי גוי גדול וגו', ולזה עצמו יכוין ה' בדברו עם יעקב טעם שמסכים על ישיבת יעקב במצרים הוא לסיבת גוי גדול אשר הוא אבוד שם בקליפת מצרים וצריך הוא להוציאו משם, וזולת ירידת יעקב אין תקוה לזה כי בעוצם קדושתו ישאב כל ענפי הקדושה אשר שם מה שאין זולתו יכול עשוהו. ולזה תמצא שאמרו ז''ל (ב''ר פ' ע''ט) שלא מת יעקב אבינו עד שראה ס' ריבוא יוצאי חלציו, ואותם ס' ריבוא נתענו שם אחר כך ונצרפו בכור הברזל בעוני מצרים ויצאו מזוקקים, וממוצא דבר הרגיש יעקב כי רצונו יתברך לשבת שם יעקב ובהבטחת כי לא יירא מעבור עליו שעבוד ועינוי, ועודנו בצער קבורת הארץ לזה אמר אנכי ארד עמך וגו' ואנכי אעלך וגו':
@48 **עוד** יכוין לומר לו טעם אשר חפץ הוא שיתקיים השעבוד והעינוי במצרים שבזה יהיה הדבר כבד על בניו כי לגוי גדול וגו' שהוא שם ומוכרח הדבר להיות כן:
@49 **אנכי ארד מצרימה וגו'**. מהכתוב משמע כי ירדה עמו שכינה, וקשה לדבריהם ז''ל (שמו''ר פ' י''ב) שאמרו כי מצרים להיותה מלאה גלולים לא היתה שכינה שם, ולזה היה משה צריך לצאת חוץ לעיר להתפלל דכתיב (שמות ט כט) כצאתי את העיר:
@49 **ואולי** שכוונת דברי ה' היא על דרך אומרו (תהלים צא) עמו אנכי בצרה שרמז לו כי כביכול יסבול עמו הצרה, והוא אומרו **אנכי ארד עמך מצרימה** פירוש לשון מיצר, וכמו שמצינו שנגלה למשה בסנה להראותו כי שוכן בסנה מקום קוצים לצד צער ישראל, ולעולם לא ירדה שכינה למצרים מקום המטונף, אלא שראיתי שאמרו ז''ל בכמה מקומות כי שכינה עמהם במצרים כאומרם (מגילה כט:) גלו למצרים שכינה עמהם, וכן אמרו (תנחומא ויחי) וישתחו ישראל על ראש המטה לשכינה שהיתה וגו', ואמרו עוד (ב''ר פ' צ''ד) כי השכינה השלימה מנין שבעים נפש שירדו למצרים כי בפרטן אינם אלא ס''ט, הרי כי שכינה ירדה למצרים:
@49 **אכן** אשכילך כי הדרגות אור השכינה רבים המה הלא תמצא שעשרה שיושבים ועוסקים בתורה (אבות פ''ג) שנו רבותינו כי שכינה שרויה ביניהם, ואפילו ב' ואחד אמרו ז''ל כי מצויה שכינה, ומצינו שלא ירדה שכינה ביניהם של ישראל אלא אחר שעשו המשכן ואחר כמה הכנות האמורים ובירידתה ראו מעשה ה' וכבוד ה' מלא המשכן (שמות מ לה) מה שאין הרגש כן ולא כיוצא בו בשעה שעוסקים בתורה אפילו אלף, אלא ודאי יש הדרגות אין מספר להם להשראת שכינה בסוד כי גבוה מעל גבוה שומר, (קהלת ה') ויתרבה האור בהשראתו כפי בחינת הסובב השראת השכינה, וצא ולמד השראת השכינה בהר סיני ולמטה ממנה השראתו בבית המקודש ולמטה ממנו השראת שכינה על הנביא ובית הכנסת ובית המדרש ובין עשרה שעוסקים בתורה ולמטה בהדרגות המנין. ובזה נתישבו דבריהם ז''ל כי לא ירדה שכינה שהיא בחינת אור הגבוה ביותר שהוא המנבא, ולזה אמר משה כצאתי את העיר, אבל בחינת אור המצוי אצל לומדי תורה וכיוצא ירד עם יעקב אבינו ושם היה עד יום צאת ישראל ממצרים, והגם שבאורו יתברך לא יוצדק לעשות הפרש, זה אמת כי באלהותו יתברך הוא אור שוה אבל באור המבהיק ממנו הוא שיתיחס אליו בחינות ההדרגות, וזה גם כן ימצא בבחינות הנשמות שהם אור מאור כסא כבודו יתברך יש ביניהם הפרשות מופלאות והבן. ובזה מצאנו גם כן נחת רוח במה שאמר הכתוב **ואנכי אעלך** שכפל לומר פעם ב' ואנכי ולא הספיק במה שכתב בתחלה אנכי ארד וגו' שנתכוון לומר על הבחינה העליונה אעלך וגו' והוא סוד אומרו (יתרו) אנכי ה' אלהיך והיא בחי' שכינה העליונה שנת היובל שנת המ''ט והוא סוד מ''ט פעמים שנזכרה יציאת מצרים בתורה:
@49 **עוד** יכוון באומרו **ואנכי** פעם ב' רמז לו שההצלה תהיה על ידו יתברך, והוא על דרך אומרו (מכילתא בא) ויוציאנו ה' וגו' לא על ידי מלאך ולא וגו' אלא הקב''ה בכבודו וגו', והוא אומרו ואנכי בכבודי אעלך וגו':
@49 **וטעם** כפל **אעלך גם עלה**, רמז לו ב' עליות האחד יציאת מצרים, והב' שיעלהו משם לבל יקבר בארץ מצרים שהוא המורא שהיה ירא כמו שכתבנו למעלה, ואמר תיבת גם לרמוז תוספת הריבוי שיעלו בו ממצרים בין בבחינת המעלה בין בבחינת הבירורים שיבררו שמה ניצוצי הקדושה לאין קץ:
@49 **או** ירצה **גם עלה** לרמוז אל חלק הרוחני היורד עמו מצרים, ועיין בזוהר (שמות ד') בפירוש פסוק יצאו כל צבאות ה':
@49 **ויוסף ישית ידו וגו'**. נתכוון להבטיחו שלא ימות בחייו, גם לצד שכמה פעמים הזכיר יעקב זכרון המות על יוסף ואמר גם כן (וישכ לח) כי ארד אל בני וגו', לזה חזר להבטיחו שלא יחוש לשגגה היוצאה (קהלת י') וגו':
@49 **עוד** נתכוון לומר אליו כי העליה של יעקב לא תהיה בחיים חיותו אלא לאחר מיתה והוא אומרו **ויוסף** וגו', גם מזה ידע כי אין לו רשות לצאת ממצרים בחיים חיותו כדי שיקוים דבר ה' שישית יוסף ידו על עיניו ואם יצא אין הדבר יכול להתקיים:
@51 **ויקחו את מקניהם וגו'**. טעם שלא אמר כן בתחילת הנסיעה כשאמר (א') ויסע וגו'. אולי כי מקודם לא נסעו אלא ללוות יעקב גם לראות פני יוסף אך אחר מראה הנבואה נתגלה להם כי מסכים אל עליון שיגורו שם במצרים עד יום שירצה להעלותם משם וכמו שטר חוב הגלות אלא נשאו טפם וגו' ויבואו מצרימה:
@52 **בניו ובני וגו'**. אחר שאמר בסמוך יעקב וכל זרעו לא היה צריך לומר פעם ב' בניו ובני וגו':
@52 **עוד** צריך לדעת למה הפסיק בין בניו ובני בניו לבין בנותיו ובנות בניו וכל זרעו בתיבת אתו, ולא הספיק במה שאמר לבסוף הביא אתו מצרימה:
@52 **אכן** כוונת הכתוב הוא שבא להודיע כי יש הפרש בין בני יעקב בירידתם למצרים כי יש מהם שבאו ברצונם לקבל גזירת מלך בלב שלם ויש מהם שהיו חוככים להתעכב מרדת לכור הברזל, וציינם הכתוב מי ומי ההולכים לפרוע שטר חוב הגלות מרצונם, ואמר **בניו ובני בניו אתו** פירוש אלו לא הוצרך להביאם הוא אלא הם מעצמם באו אתו בדומה לו, ואחר כך סדר אותם שלא באו מרצונם עד שהוצרך יעקב להורידם בעל כרחם, והוא אומרו **בנותיוובנות בניו וכל זרעו** פירוש בני בני בניו אלו הביא אתו מצרימה פירוש הוא הביאם לא לרצונם באו:
@52 **וראיתי** לתת לב לדבריהם ז''ל (שמו''ר פ''א) שאמרו שכל זמן שאחד מיורדי מצרים קיים לא התחיל השעבוד דכתיב (שמות א') וימת יוסף וגו' וכל הדור ההוא פירוש שירדו מצרים אז התחיל השעבוד, כי אולי שזה היה להם לתשלום קבלת גזירת מלך ברצון פקע מהם השעבוד כי סמא דיסורי קבולי. והעד הנאמן לזה גם כן כי יוכבד וסרח בת אשר היו מיורדי מצרים (ב''ר פ' צ''ד) ובימיהם היה השעבוד, והטעם הוא לצד שהביאם יעקב ולא מרצונם, ועיין בדברי הזוהר (ויקהל קצח.) בפירוש פסוק אשרי שאל יעקב בעזרו שברו על ה':
@53 **ואלה שמות וגו'**. יש להעיר בפירוש מספר זה, א' למה הוצרך לומר **יעקב ובניו**, גם אין לה משמעות בהרדפת הענין. ב' אומרו (ט''ו) **כל נפש בניו** וגו' **שלשים ושלש**. ובפרטן אינם כי אם ל''ב. ורז''ל הרגישו מזה ואמרו (ב''ר פ' צ''ד) שהיא יוכבד שנולדה בין החומות, ודבריהם ז''ל יקובלו מפיהם ולא מפי זולתם כי אין ראיה לזה מהכתוב. גם מהם אמרו (שם) כי שכינתו יתברך היא המשלמת ע', ולדבריהם ז''ל אין כאן יוכבד במנין שאם לא כן שלמים הם במספר הע', ודבריהם ז''ל יוצדקו ביישוב פסוק (כ''ז) הבא באחרונה כל הנפש הבאה וגו' שבעים לא בפסוק זה כי למה יצטרף לבני לאה לבד וא''כ מה יענה בל''ג שאינם אלא ל''ב. ולמדרש שאמר זו יוכבד וכו' ודאי שיחלוק על מדרש הנזכר, וקשה לי גם עליו כי לפי דבריו שאמר שיוכבד נולדה ובה נשלמו ל''ג בני לאה אם כן למה כשחזר הכתוב לכלול כל פרטי המניינים בסמוך אמר (כ''ו) כל הנפש הבאה ליעקב וגו' ששים ושש ואם נולדה יוכבד יהיה החשבון ששים ושבע, על זה הדרך, ל''ג של לאה, ששה עשר של בני זלפה הרי ארבעים ותשע, אחד עשר של בני רחל מלבד יוסף ושני בניו שהיו במצרים הרי ששים, ושבעה של בני בלהה הרי ס''ז, ולמה יכחיש הכתוב עצמו ויאמר כל הנפש וגו' ששים ושש ובפרטן הוא מונה ששים ושבע. עוד יש לתמוה כי חזר באחרונה וצירף יוסף ובניו וגו' ואמר כל הנפש וגו' שבעים, ואינו כן, הן אמת לדברי המדרש שצירף ה' עמהם שכינתו יתיישב פסוק זה וקשה לדבריו פסוק ראשון:
@53 **והנכון** בפשט הכתובים הוא כי ב' מנינים מונה הכתוב באחד מונה יעקב ובאחד מונה זרע יעקב, ולזה כשכולל יעקב ובניו הנה הם שבעים וכשמפרט בניו מבלעדי יעקב אינם אלא ס''ט. גם בזה ידוייקו הכתובים במה שהערנו בהם כי בתחלה הראנו באצבע כי מכנים יעקב במנין הראשון של בני לאה, והוא אומרו **יעקב ובניו** פירוש כי מכניסו בכלל מנין זה ולזה אמר לבסוף **כל נפש בניו ובנותיו שלשים ושלש** פירוש כל נפש האמורים בפרשה זו בצירוף בניו ובנותיו והוא עמהם בצירוף החשבון ולא הוצרך להזכירו וסמך על מה שרשם בתחילת הענין יעקב ובניו. ואולי כי לזה אמר תיבת **כל** לכלול האב עם הבנים במספר זה. ותמצא שבצירוף בני זלפה שאמר בסמוך אמר (י''ח) ותלד וגו' שש עשרה נפש ולא אמר כל, והגם שבמספר בני רחל (כ''ב) אמר כל להיות שרצה לכלול בני יוסף שבהם עולה החשבון לסכום הרשום, ומה שאמר (כ''ה) כל בבני בלהה נתכוין לומר שאין בכולן אלא שבע חשבון קטן:
@53 **עוד** תמצא שבכל שלשת האמהות אמר זכרון הלידה בזלפה אמר ותלד את אלה וגו', ברחל אמר אשר יולד ליעקב, בבלהה אמר ותלד את אלה וגו', מה שלא אמר כן בבני לאה, ולדרכינו נתכוון הכתוב להעיר כי לא כל הל''ג הם נולדים, ולזה אם היה אומר ותלד אלה ליעקב שלשים ושלש היה הנשמע כי שלשים ושלש ילדה ולא כן הוא שלא ילדה אלא ל''ב ובצירוף אביהם עם בניו ובנותיו ל''ג, ואשר על כן כשצירף באחרונה העירך כי חשבון הבנים ובנות בפני עצמן לבד מיעקב אינו כן, והוא אומרו בצירוף פרטי החשבון. כל הנפש הבאה ליעקב הרי הוציאו מכלל החשבון ודקדק לומר יוצאי ירך יעקב ששים ושש, ולא תקשה קושייתנו שששים ושבע, כי שם כלל יעקב וכאן לא כללו, ובצירוף מספר הכל לבסוף אמר כל הנפש לבית יעקב פירוש הוא ובניו שבאו מצרימה שבעים:
@53 **גם** שנתחכם הכתוב להעירך למה שפירשנו במה שדקדק לשנות דבריו בב' כתובים הבאים כאחד בב' הצירופים, באחד דקדק לומר **כל הנפש הבאה ליעקב** הקדים הביאה להזכרת יעקב, ובפסוק ב' אמר **כל הנפש לבית יעקב הבאה** הקדים הזכרת יעקב להזכרת הביאה נתכוון בזה לומר כי בצירוף חשבון ראשון אין יעקב בכלל ולזה אמר **הבאה ליעקב** פירוש הבאה לו הא למדת כי הוא אינו בכלל, ובצירוף חשבון ב' אמר כל הנפש שיש לבית יעקב שבאו מצרימה וגו' הא למדת כי יעקב לא יצא מהכלל:
@53 **וכדי** שלא לסתור ח''ו דברי רז''ל שאמרו יוכבד נולדה בין החומות אולי שרמזה הכתוב באומרו **כל נפש** וגו' ובנותיו ולא מצינו לו אלא בת אחת אלא זו יוכבד שנולדה בין החומות, אבל לא כללה בחשבון כי יעקב הוא המשלים כמו שכתבתי. ויש עוד טעם בדבר שלא תכלל בחשבון כי אם נולדה בין החומות וצריכה ל' יום כדי שתצא מכלל נפל ולא היתה ראויה להימנות בכניסתם. ולא יקשה בעיניך שיהיה פרושינו הפך דברי חז''ל, כי כבר הודעתיך כי בפשטי התורה שאין הלכה יוצאה מהם רשות נתונה לתלמיד ותיק לחדש, ועליהם נאמר (שה''ש ה') חכו ממתקים וכולו מחמדים.
@53 ויש ליישב מה שהקשינו לדבריהם ז''ל והוא דחוק והפשט כראי מוצק (איוב ל''ז) והדרשה תדרש:
@57 **ובני יהודה ער ואונן וגו'**. צריך לדעת לאיזה ענין הזכיר אותם שכבר מתו. גם אין חידוש בהודעת מיתתם. גם צריך לדקדק אומרו **ויהיו בני פרץ** וגו' שהיה לו לומר ובני פרץ וגו' כאומרו אחר זה ובני בריעה מה היא כוונתו באומרו **ויהיו** וגו'. ואפשר כי לפי מה שקדם אצלנו במצות יבום כי יביא נפש המת, ובמציאות שלפנינו לצד שמתו ער ואונן בלא בנים ויוצרך המיבם להביאם והנה נעשה יהודה מיבם בעד שלה והביא ב' הנפשות עצמן, והודיע הכתוב כי ער ואונן במקומן עומדים שנכנסו במקומן חצרון וחמול, וזה הוא שיעור הכתוב ובני יהודה ה' בנים ער ואונן וגו' וימת וגו' ולצד זה היו ער ואונן חזרו להיות בני פרץ חצרון וחמול כי חזרו לעולם מעוברים בסוד נפש מת והיו חצרון וחמול:
@57 **ובדרך** פשט יכוין הכתוב בהזכרת ער ואונן ללמד עליהם זכות כי טעם מיתת ער ואונן היה לצד שהיו בארץ כנען על דרך אומרו (אחרי י''ח) כמעשה ארץ מצרים וכמעשה ארץ כנען וגו' ואמרו ז''ל (ויק''ר פ' כ''ג) השוה הכתוב מעשה מצרים וכו', ולצד שהיו שם ער ואונן למדו ממעשיהם וזולת זה בניו של אותו צדיק אין שורשם רע ומר ח''ו, ותמצא שיצו האל ישראל לבל ילמדו מהם דכתיב כמעשה וגו':
@57 **וטעם** אומרו **ויהיו** רמז כי לאלה יקרא הויה ואין כמותם לצד כי מהם יצא חוטר לישי משיחנו מלכנו אשר יהיה לנס עמים אליו גוים ידרושו:
@75 **ויאמר וגו' אמותה הפעם וגו'**. טעם אומרו **הפעם** פירוש להיות שאמר (וישב ל''ז) כי ארד אל בני אבל שאולה עתה אמר לא אראה השחת:
@75 **עוד** נראה לומד בדקדוק אומרו **כי עודך חי** ולא הספיק לומר אחרי ראותי פניך והדבר מובן כי חי הוא. גם צריך לדעת למה לא אמר יעקב כן כשבשרוהו האחים כי יוסף חי ומצינו שהאמין כשראה העגלות (מ''ה) ותחי רוח וגו' ומה דבר חדש ראה:
@75 **אכן** כוונת דברי יעקב הם כי הגם שנתבשר כי עודנו חי זה הועיל לדעת שישנו במציאות אבל עדיין לבו דוי עליו לצד היותו בין האומות שפל עבד מושלים אם עודנו בצדקותו ולא כהתה עינו ולא נם ליחו, או לצד היותו מובדל ממנו ונתון תוך הקליפות ובפרט טומאת מצרים, ומה גם לצד מה שעברו מרוח הקודש שאמר (ל''ז) טרוף טורף יוסף חיה רעה אכלתהו, (ב''ר פ' פ''ד) ודבר ידוע הוא כי הצדיקים יותר יחפצו בהעדר הבן בהיותו בן מביש ומה גם יעקב הצדיק, אשר על כן לא היתה שמחתו שלימה מספק זה עד וירא אליו והכיר בו בפניו כי הכרת הפנים תענה באיש, וכמו כן מצינו לצדיקים שלמים וכן רבים שהכירו ברושם הפנים מעשה אדם ומכל שכן יעקב אבינו שיכיר, לזה כשהכיר בו אמר אליו אמותה הפעם פירוש הפעם הזאת בראייתך ולא מקודם כשנתבשרתי, והטעם **אחרי ראותי פניך** והכרתי בהם שעודך חי פי' צדיק כמקודם ולא נשתנה דיוקנך מכמות שהיה אלא עודך חי כי הצדיקים קרויים חיים (ברכות יח.) ונכון:
@80 **אבי ואחי וגו'**. פירוש כאשר צוית עליהם עשות. **והנם בארץ גושן** כמו שאמרת (מ''ה) ואתנה לכם את טוב ארץ מצרים, וארץ גושן בערך מרעה המקנה היא טוב ארץ מצרים, אבל האחים בדברם לפני פרעה לא באו בטענה כאשר אמרת אלא כמתחנן על דבר טוב, ואמרו (ד') לגור וגו' כי אין מרעה וגו' ועיין בסמוך:
@84 **ויאמר פרעה וגו' לאמר וגו'**. צריך לדעת כוונת אומרו **לאמר**, גם קשה אומרו **אביך** וגו' **באו אליך** הרי זה בא ללמד ונמצא למד בדבר עצמו שלימד:
@84 **אכן** תמצא כי פרעה בדברו אל יוסף ענין אחיו שיקחו את אביהם ויבואו אמר (מ''ה י''ז) אמור אל אחיך זאת עשו וגו' וקחו את אביכם וגו' ובואו אלי, ודבר זה יש בו ב' משמעיות, הא' כי ידבר אליהם משם פרעה כי הוא המצווה דבר. והב' כי יוסף יאמר להם כן מפי עצמו, ופירוש זה הוא יותר צודק ממה שמצינו שאמר אחר כך (שם י''ט) ואתה צויתה וגו' ואם הכל הוא דברי פרעה לא יצטרך לומר שנטל רשיון מפרעה הלא הכל הוא דברי פרעה. והנה תמצא כשדבר יוסף אל אחיו קודם שידבר לפרעה אמר להם (מ''ו ל''א) אעלה ואגידה לפרעה וגו' אחי וגו' באו אלי הרי גילה דעתו כי הוא המצווה אותם לבא אצלו והנה באו אליו האנשים, וזה הצדיק פירוש ב'. וכאשר דבר אל פרעה לא דקדק לומר באו אלי אלא סתם אחי וגו' באו מארץ כנען וגו' זה יגיד כי ביאתם היא לפרעה ולזה מודיעו לומר קיימו דבריך וכמו שפירשתי בפסוק הסמוך לזה, אשר על כן השיב פרעה ליוסף לאמר **אביך ואחיך באו אליך** פי' שתאמר שביאת אחיך באו אליך כי אין כונתי באומרי אמור אל אחיך זאת עשו בשליחותי תדבר אליהם כי אני המצוה אלא הרשיתי אותך שתדבר אליהם משמך שיבואו אליך, וכבר הרשיתי אותך שתתן להם טוב ארץ מצרים ואם כן ארץ מצרים לפניך היא במיטב הארץ וגו'. וההפרש שבין אם יהיה הדבר במצות פרעה או על פי יוסף יש בזה לומר צד גנאי וצד שבח, צד גנאי ששלל החיוב ממנו אליהם, ועוד כי מנימוסי המלכות כשיתן מלך גדולה או הנאה לאדם אחד היא לו מתנת עולמית, ולזה אם יהיו הדברים הנאמרים מפי פרעה הנה הנם באים למאמר המלך וחיוב על המלך לסבול עולם ומיטב הארץ יותן להם נצחי במלכותו, ולזה הקפיד פרעה שלא יהיה הדבר ממנו אלא מיוסף והחיוב אליו הוא ולא על פרעה ובזה אין מתנתו עולמית כי אינו אלא שליט בארץ מצרים ואין לו שם מלכות ומתנתו תהי' קיימת כל זמן שיחפוץ המלך בה, ובזה נתכוון שלא יחשוב יוסף כי הוא צריך להם ולצורך המלכות שלח אחריהם להיותם גבורי חיל להיות חיל וחומה למלכותו לזה אמר אליו כי הוא אין לו צורך בהם:
@84 **וצד** השבח הוא כי למה יצטרך להודיעו הדבר כאיש אשר אין כח בידו לעשות דבר עד שיקח רשות מאת המלך הלא כבר ניתן לו רשות בכל ועשה יעשה, והוא אומרו **באו אליך** ראוי אתה שיבואו בשבילך ובכח מאמרך ארץ מצרים לפניך היא במיטב הארץ וגו' מבלי צורך קחת רשות ממני, ולדרך זה תתפרש עוד לאמר שנתן לו רשות לומר הדברים הנאמרים אליו, והוא על דרך אומרם בפ''א ממסכת יומא (ד:) וז''ל אמר רבי מנשיא מנין לאומר דבר לחבירו שהוא בבל תאמר עד שיאמר לו אמור דכתיב וידבר ה' וגו' לאמר עד כאן, ולזה הוצרך פרעה להרשותו כי כל יקר וגדולה נאמר לו מפי פרעה, והגם שיגיע קצת פחיתות ערך פרעה באמצעות הדברים אין בכך כלום:
@84 **עוד** ירמוז בתיבת **אליך** לאמר לו כי טעם הדבר שצוה להם שיבואו אינו אלא למה שנוגע לכבודו של יוסף כדי שתוכר משפחתו במצרים שלא יהיה נחשב לשפל אנשים, והגם שהוכרו אחיו ביום שהתודע אליהם עודנו בחשד שראה כת של בחורים וכינה עצמו עליהם כאמור בדבריהם ז''ל (ב''ר פ''ק) בפסוק (נ' כ''א) וינחם אותם וידבר על לבם, ובביאת אביו ואחיו יאמן הדבר, והוא אומרו **באו אליך** לצורכך ולכבודך היא ביאתם:
@85 **במיטב הארץ וגו' ישבו בארץ גושן**. הנה חש לומר במיטב הארץ לבד, לצד שיוסף רמז בדבריו כי חפץ בארץ גושן יחשוב כי אינו חפץ שישבו בארץ גושן ממה שלא הסכים על דבריו, ואם היה אומר ישבו בארץ גושן יהיה נשמע שהוא כמסתפק להם בנתינת ארץ גושן לבד ולא בטוב ממנה אם יכשר בעיני יוסף וזה סותר מה שקדם בדבריו (מ''ה) ואתנה לכם את טוב ארץ מצרים, לזה אמר במיטב וגו' בארץ גושן. וזה שיעור דבריו במיטב הארץ הושב וגו' ואני מודיעך כי ארץ גושן היא המיטב. ומצינו שכן העיד הכתוב דכתיב (פסוק י''א) ויושב יוסף וגו' במיטב הארץ בארץ רעמסס וגו':
@85 **או** יהיה שיעור הכתוב על זה הדרך **במיטב** וגו' ואם בחרו להם ארץ גושן ישבו בה. ובזה אין החלט לומר כי הוא זה מקומם אלא עודם בשער הרצון אם ייטב בעיניהם מקום אחר הרשות בידם לשבת במיטב הארץ:
@86 **ויעמידהו לפני פרעה**. טעם אומרו **ויעמידהו** וגו'. אולי שהעמידו במקומו של יוסף ששם לו פרעה מקומו לפני כסאו כשאמר לו (מ''א) רק הכסא אגדל ממך, והודיע הכתוב כי יוסף העמיד אביו לפני פרעה במקום המעולה קרוב למלך:
@86 **עוד** ירצה שהעמידו למול פניו כדרך המברכין ויברך יעקב וגו':
@86 **עוד** ירצה להודיע כי הוצרך להעמידו לפניו לצד היות פרעה שפל אנשים צעיר קומה (מ''ק י''ח) הוצרך להכירנו לו והעמידו לפניו לומר כי הוא זה:
@92 **ולחם אין וגו' כי כבד וגו'** פירוש ולצד כובד הרעב היו אוכלים דבר מופלא וכילו הלחם והלא לראות עינינו דאבה נפשינו בשני רעב שהיו במערב שהיה אדם אחד אוכל שיעור מאכל י' בני אדם ועודנו רעב בבטנו רחמנא ליצלן:
@93 **וילקט וגו'**. אמר לשון לקיטה פירוש שלא נשאר מהכסף בידם ולא כלום כי לא הניח אחריו לקט:
@94 **ולמה נמות וגו'כי אפס כסף וגו'** פירוש להיות שלא היה חפץ לקחת בשכר התבואה כי אם הכסף ולא פרעון אחר ואשר מצד זה לקט כל הכסף הנמצא, ועתה באו בטענה לומר למה וגו' לטעם שתם הכסף שהרי יכולין המה לפרוע התבואה בשוה כסף ולזה השיבם יוסף שנתרצה לקחת מקניהם בעד הלחם כיון שתם הכסף ודקדק בדבריו לומר **אם אפס כסף** וזולת זה לא יתן להם כל עוד שיש להם לפרעו בכסף, וטעמו להעני מצרים כדי שלא יהיו אחיו דלים בפני עשירים ולזה נתחכם שיקנו ממנו בכסף שכל עוד שהמקנה בידם מזונותם עליהם ויצטרכו לקנות לחם להם ומזונות המקנה כי מן הסתם אין דשא ואין עשב וצריכין לתת שעורים מאכל לבהמות לזה הניח צורכי המקנה עליהם וישבור להם בכסף שבזה לא נשלמה שנה ראשונה עד שהורקו ונעשו כלי ריק מכל וכשבאו אחיו היו עשירים לפני עניים והיו לכבוד ולתפארת מה שלא היה כן אם היה מקדים לקחת מהם המקנה:
@94 **עוד** נראה שיכוונו לומר שיש להם כסף אלא שאינו בנמצא להם אז וזה הוא דבר הרגיל שבני אדם לא יהי' להם מצוי תמיד כסף כי ישלחו בארץ מרחקים, והוא אומרו **אפס** לשון מניעה ולזה טענו למה ימותו לצד שכספם במקום אחר והשיבם כי יתנו מקניהם אם נמנע מהם הכסף וכוונתו הוא אם אמת דבריהם שיש להם כסף אלא שאינו מצוי וזה יורה שאינו מצדיק דבריהם ואמר להם שיתנו לו מקנה הבהמה משכון בעד הכסף עד שיגיע לפרק התקבל ואז יחזיר להם המקנה:
@97 **לא נכחד מאדוני וגו'**. קשה מה כוונתם באומרם **לא נכחד** והאיך יכולין לכחד בדבר שעומד להתברר שאם יאמרו כי לא תם צריכין להביאו ומה היא אמנה זו שאומרים לו שלא יכחידו את הדבר. עוד צריך לדעת אומרם **כי אם** שאין להם משמעות. עוד הלא כבר אמרו לו בשנה ראשונה אפס כסף:
@97 **עוד** צריך לדעת כוונת אומרם **ומקנה** וגו' **אל אדוני**. ואולי שנתכוונו לומר על זה הדרך **לא נכחד** וגו' פירוש אין לנו כסף ואנו מכחידים אותו מאדוני כי אם האמת במה שהוא תם הכסף, וכוונתם לבל יחשדו אותם כי הענו עצמם ובאו לבקש בתורת צדקה. ואומרם **ומקנה הבהמה אל אדוני** פירוש כל מה שיש ממקנה הבהמה הוא של אדוני כי הוא לא עשה גבול למקנה אלא בדרך כלל קנה הכל כאומרו וינהלם בכל מקניהם, לזה אמרו כי לא הוצרכו לומר לא נכחד אלא בכסף שהוא דבר שיכול להטמן אבל מקנה הבהמה כל מה שיש להם הוא של אדוני בכל מקום שהם שלו הם. ואומרם **לא נשאר** וגו'. לומר שאין להם לא כסף ולא שוה כסף:
@97 **ולפי** מה שפירשתי בפסוק כי אפס כסף בדרך ב' כי טענו שיש להם אלא שאינו מצוי בידם יתיישב הכתוב על נכון כי באו ואמרו לו לא יכחדו דבר ממנו כפעם ראשונה שטענו שקר שהיה להם אלא שמנע מהם לא כן הוא כי אם תם ממש פירוש נשלם ואין להם עוד כסף. ובזה ידוייק למה בפעם ראשונה אמרו אפס ובפעם ב' אמרו תם:
@97 **ואומרם ומקנה הבהמה אל אדוני** פירוש מקנה הבהמה אשר היה עד עתה לבטחון עד שיזדמן הכסף מעתה יהיה מוחלט לך, והוא אומרו אל אדוני:
@102 **הן קניתי אתכם היום**. טעם אומרו **היום**, גם הטיל תיבת היום, בין קנייתם לקניית האדמה. כי קנייתם הוא על ידי משיכה כדין קניית עבדים (קידושין כב:) ובמעשה שעשה שהעביר העם לערים מקצה וגו' זו היא קנייתם, לזה אמר **הן קניתי אתכם היום** פירוש במה שהעבירם אז לערים. אבל האדמה אין זה דרך קניינה וכשהזכיר למעלה ויקן יוסף את אדמת מצרים שם נרמז כי קנאה באחד מדרכי קנין האדמה:
@102 **ויש** להעיר בדבר אחר שקנה אותם מה צורך לקניית אדמתם הלא מה שקנה עבד קנה רבו, (פסחים פח:) ואולי כי לצד שלא היה קניינם כקנין עבדים אלא לפרט זה לעבוד את האדמה וגו' ולתת חמישית לפרעה אין זה אלא כקנין שכיר שלא קנה קניינו ולזה הוצרך לקנות האדמה וקנה אותה בקנין גמור כמו שגילה הכתוב באומרו ויקן יוסף את כל אדמת מצרים וגו' כי מכרו מצרים איש שדהו, ואם ירצה פרעה להביא פועלים ולעבוד האדמה לזכותו ולאחדיותו עשה יעשה מה שאין כן גופם של מצרים לא אמר שקנה קנין גמור. והגם שאמר הן קניתי אתכם פירוש כקנין שכיר לדבר המוזכר בדברי יוסף הא לכם זרע וגו'. וטעמו של יוסף כי מה יועיל באדמה אם אין עובד לזה נתחכם לקנותם לחייבם על העבודה:
@103 **חמישית לפרעה וגו'**. נתחכם לומר כי קודם כל דבר יטול פרעה חמישית הזרע ומשכחת לה שישאר בד' הידות שיעור המספיק לזרע השדה והם יצאו נקיים אף על פי כן לא יגרע מהחמישית לפרעה, אחר כך ולזרע השדה ויקדימו זרע השדה ואחר כך יטלו המה כל הנשאר אם מעט ואם הרבה:
@103 **וטעם** אומרו **ולאכול לטפכם** ולא כללם לאשר בבתיכם, להיות שהטף מנתם מרובה כנגד חלק העודף אמר ולאכל לטפכם:
@104 **והיינו עבדים לפרעה**. דקדקו לשלול כי עבדותם לפרעה ולא ליוסף:
@104 **עוד** יכוונו לומר על דרך מה שפירשתי למעלה כי לא קנאם אלא לפרט עבודת האדמה, לזה אמרו והיינו עבדים בהחלט העבדות לפרעה ולא לעבודת האדמה לבד. ואולי כי לזה נתכוונו כשנדברו מצרים עם פרעה על ישראל ואמרו (שמות א') הנה עם בני ישראל רב וגו' ממנו פירוש כי אין לו שם עבדות ככולן שהיו עבדים לפרעה:
@106 **וישב ישראל בארץ מצרים וגו'**. צריך לדעת למה כפל לומר בארץ מצרים בארץ גושן: **עוד** מה קשר ושייכות לויפרו וגו' עם וישב ישראל:
@106 **אכן** יתבאר הכתוב על פי מה שכתבנו בפסוק (מ''ו ג') כי לגוי גדול וגו' כי סיבת ירידת מצרים היא להעלות ניצוצי הקדושה אשר נתפזרו ובאו שמה, והוא אומרו **וישב ישראל בארץ מצרים** פירוש שהיא מקום קליפה המזוהמת, בארץ גושן מלשון הגשה כי שמה הוגשו כל ניצוצי הקדושה באמצעות ענף הקדושה שהוא ישראל שהוא בבחינת אבן השואבת לדומה לו. ואמר לשון יחיד רמז אל היותם בלב מיוחד כולם ואין ביניהם פירוד ובאמצעות כן **ויאחזו בה** פירוש אחזו דבר כה והם הניצוצות הנזכרים ובזה **ויפרו וירבו** כי כשיתרבו הנפשות יתרבו הנולדים, ועיין מה שפירש המגיד למהרי''ק בפירוש פסוק וימת יוסף וגו' ובני ישראל פרו וישרצו וירבו ותמצא עזר לדברינו דכרי אלהים חיים:
@106 **חסלת פרשת ויגש**
